insert into public.quiz_item (id, kp, kind, level, body, src, status) values
  ('pro-where-1', 'pro-where', 'mc', 1, '{"q":"隔著臺灣海峽，在臺灣西邊的是哪裡？","opts":["中國大陸","菲律賓","日本"],"a":0,"why":"臺灣海峽是臺灣和中國大陸中間的那片海，所以隔著海峽的西邊就是中國大陸。菲律賓在南邊、隔著巴士海峽；日本在東北邊。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉', 'draft'),
  ('pro-where-2', 'pro-where', 'tf', 1, '{"q":"臺灣的東邊是一大片太平洋。","a":true,"why":"臺灣東邊的海岸直接面對世界最大的太平洋，所以花蓮、臺東的海又深又藍。西邊則是比較窄的臺灣海峽。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉', 'draft'),
  ('pro-where-3', 'pro-where', 'cat', 2, '{"q":"把臺灣的鄰居放到正確的方向。","cats":["北邊、東北邊","南邊","西邊"],"cards":[{"t":"日本","c":0},{"t":"琉球群島","c":0},{"t":"菲律賓","c":1},{"t":"中國大陸","c":2}],"why":"記法：北上是日本和琉球、南下是菲律賓（中間隔著巴士海峽）、往西過臺灣海峽是中國大陸，東邊是太平洋。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉', 'draft'),
  ('pro-wind-1', 'pro-wind', 'cloze', 1, '{"q":"選出正確的季風。","text":"臺灣冬天吹{0}，夏天吹{1}。","blanks":[{"opts":["東北季風","西南季風"],"a":0},{"opts":["東北季風","西南季風"],"a":1}],"why":"季風是跟著季節換方向的風。冬天冷空氣從北方大陸吹來，所以是東北季風；夏天溫暖的風從南邊海上吹來，所以是西南季風，兩個方向剛好相反。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣的自然環境與生活〉', 'draft'),
  ('pro-wind-2', 'pro-wind', 'tf', 1, '{"q":"黑潮是一道在臺灣東邊、往北流的海流。","a":true,"why":"黑潮是一道溫暖的海流，從菲律賓那邊往北流，經過臺灣東邊的海。它帶來很多魚，也讓臺灣東部的海水比較溫暖。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣的自然環境與生活〉', 'draft'),
  ('pro-wind-3', 'pro-wind', 'who', 2, '{"q":"從前的人坐帆船出海，誰的想法比較有道理？","says":[{"n":"阿明","t":"什麼時候出發都一樣，划快一點就好"},{"n":"小華","t":"要看季風和海流，順著風走比較省力"},{"n":"阿美","t":"一定要等沒有風的日子才能出發"}],"a":1,"why":"以前的帆船沒有引擎，要靠風推著走，划得再快也比不過逆風。所以小華說得對：要看季風和海流，順著走才省力；沒有風的話帆船根本走不動。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣的自然環境與生活〉', 'draft'),
  ('pro-land-1', 'pro-land', 'mc', 1, '{"q":"臺灣最高的山是哪一座？","opts":["阿里山","玉山","陽明山"],"a":1,"why":"玉山大約 3952 公尺，是臺灣也是東亞最高的山之一。阿里山是有名的森林遊樂區，陽明山在臺北，它們都比玉山矮很多。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣的自然環境與生活〉', 'draft'),
  ('pro-land-2', 'pro-land', 'mc', 2, '{"q":"臺灣的平原大多在哪一邊？","opts":["東部","西部","中央"],"a":1,"why":"臺灣中間有高高的中央山脈，像屋頂一樣把島分成東西兩邊。東邊山很靠近海，平地很少；西邊有比較寬的平原，所以大城市和農田多在西部。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣的自然環境與生活〉', 'draft'),
  ('pro-land-3', 'pro-land', 'multi', 2, '{"q":"早期的人喜歡在哪樣的地方蓋村莊？（選兩個）","opts":["地勢平坦的平原","靠近河流、方便取水","很高很陡的山頂","四周都沒有水的地方"],"a":[0,1],"why":"蓋村莊要能種田、喝得到水。平原平坦好開墾，河邊方便取水；山頂又陡又難種田，沒有水的地方更住不下去。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣的自然環境與生活〉', 'draft'),
  ('pro-tropic-1', 'pro-tropic', 'mc', 1, '{"q":"北回歸線經過臺灣的哪兩個地方？","opts":["嘉義和花蓮","臺北和宜蘭","高雄和屏東"],"a":0,"why":"北回歸線是一條看不見的線，橫過臺灣中南部，經過嘉義和花蓮。兩個地方都蓋了北回歸線標誌，可以去找找看。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣的自然環境與生活〉', 'draft'),
  ('pro-tropic-2', 'pro-tropic', 'tf', 2, '{"q":"北回歸線的南邊是熱帶，所以臺灣南部通常比北部熱。","a":true,"why":"北回歸線以南屬於熱帶、以北屬於亞熱帶。臺灣南部在熱帶，太陽比較直射，所以通常比北部熱。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣的自然環境與生活〉', 'draft'),
  ('pro-rain-1', 'pro-rain', 'mc', 2, '{"q":"冬天常常下雨的是哪裡？","opts":["基隆、宜蘭","臺南、高雄","澎湖、金門"],"a":0,"why":"冬天的東北季風從海上帶來很多水氣，先碰到東北部的山被擋住，水氣往上爬變冷，就下成雨。所以基隆、宜蘭冬天常下雨，南部反而比較乾。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣的自然環境與生活〉', 'draft'),
  ('pro-rain-2', 'pro-rain', 'order', 3, '{"q":"排出「基隆冬天下雨」的順序。","steps":["東北季風吹過海面","風帶著很多水氣","碰到臺灣東北部的山","水氣變成雨落下來"],"why":"順序是「風帶水氣→被山擋→變成雨」：東北季風吹過海面吸飽水氣，碰到東北部的山往上爬，越高越冷，水氣就變成雨落下來。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣的自然環境與生活〉', 'draft'),
  ('ch1-tools-1', 'ch1-tools', 'tf', 1, '{"q":"磨製石器是加水和砂慢慢磨出來的，表面比較光滑。","a":true,"why":"磨製石器是先把石頭敲出大概的形狀，再放在磨石上加水和砂慢慢磨，所以表面光滑、刀口鋒利。只用敲的是打製石器，邊緣比較粗。"}'::jsonb, '國小社會五年級上學期（康軒版）史前文化；國立臺灣史前文化博物館', 'draft'),
  ('ch1-tools-2', 'ch1-tools', 'cat', 2, '{"q":"這些工具是怎麼做出來的？","cats":["打製","磨製"],"cards":[{"t":"長濱文化的砍砸器","c":0},{"t":"卑南文化的石錛","c":1},{"t":"邊緣粗粗的石片","c":0},{"t":"光滑的石刀","c":1}],"why":"看表面就能分：邊緣粗粗的、用敲的，是打製石器（像長濱文化的砍砸器）；表面光滑、有磨過的，是磨製石器（像卑南文化的石錛、石刀）。"}'::jsonb, '國小社會五年級上學期（康軒版）史前文化；國立臺灣史前文化博物館', 'draft'),
  ('ch1-tools-3', 'ch1-tools', 'mc', 2, '{"q":"做磨製石器，比做打製石器多了哪一個步驟？","opts":["把石頭敲出形狀","在磨石上加水和砂慢慢磨","把石頭丟進火裡燒"],"a":1,"why":"兩種石器都要先把石頭敲出形狀，差別在磨製石器還要再加水和砂慢慢磨。所以多出來的步驟是「磨」，不是敲，也不是用火燒。"}'::jsonb, '國小社會五年級上學期（康軒版）史前文化；國立臺灣史前文化博物館', 'draft'),
  ('ch1-pottery-1', 'ch1-pottery', 'mc', 1, '{"q":"大坌坑文化的陶器上，常常有什麼紋路？","opts":["用繩子拍出來的紋路","用筆畫的山水","用金子貼的花"],"a":0,"why":"大坌坑文化的人做陶器時，會用纏著繩子的工具在陶土上拍打，留下一條一條的繩紋，所以叫「粗繩紋陶」。那時候還沒有毛筆畫，也沒有金子貼花。"}'::jsonb, '國小社會五年級上學期（康軒版）史前文化；國立臺灣史前文化博物館', 'draft'),
  ('ch1-pottery-2', 'ch1-pottery', 'who', 2, '{"q":"人們開始種植、住下來以後，為什麼需要陶器？誰說得對？","says":[{"n":"小安","t":"可以煮東西，也能存放收成和水"},{"n":"阿傑","t":"因為陶器可以拿來打獵"},{"n":"小芳","t":"因為搬家時陶器最輕"}],"a":0,"why":"開始種田、住下來以後，收成要存起來，食物要煮熟，水也要裝，所以需要陶罐。陶器很重又容易破，不適合拿來打獵，搬家時也不輕。"}'::jsonb, '國小社會五年級上學期（康軒版）史前文化；國立臺灣史前文化博物館', 'draft'),
  ('ch1-pottery-3', 'ch1-pottery', 'tf', 2, '{"q":"長濱文化的人已經會種田、做陶器。","a":false,"why":"長濱文化是舊石器時代，人們住在海邊的山洞，靠採集、打獵、捕魚過生活，用的是打製石器。會種田、做陶器，是後來的新石器時代（像大坌坑文化）。"}'::jsonb, '國小社會五年級上學期（康軒版）史前文化；國立臺灣史前文化博物館', 'draft'),
  ('ch1-strata-1', 'ch1-strata', 'mc', 2, '{"q":"考古學家在同一個地方挖到上下兩層土，通常哪一層比較古老？","opts":["上面那一層","下面那一層","兩層一樣老"],"a":1,"why":"土是一層一層往上堆的，就像疊書：先放的在最下面。所以沒有被翻動過的話，下面那一層比較早、比較古老。"}'::jsonb, '國小社會五年級上學期（康軒版）史前文化；國立臺灣史前文化博物館', 'draft'),
  ('ch1-strata-2', 'ch1-strata', 'tf', 1, '{"q":"沒有文字的史前時代，要靠考古挖掘和研究器物，才知道當時人怎麼生活。","a":true,"why":"史前時代還沒有文字，沒有人寫下當時的事。考古學家只能挖遺址、研究留下來的石器、陶器和骨頭，推想那時的人怎麼生活。"}'::jsonb, '國小社會五年級上學期（康軒版）史前文化；國立臺灣史前文化博物館', 'draft'),
  ('ch1-cultures-1', 'ch1-cultures', 'order', 2, '{"q":"把這些史前文化，從最早排到最晚。","steps":["長濱文化","大坌坑文化","卑南文化","十三行文化"],"why":"照工具的進步來記：長濱用打製石器（舊石器）→大坌坑開始做陶器（新石器早期）→卑南有石板屋和玉器（新石器）→十三行會煉鐵（金屬器時代）。"}'::jsonb, '國小社會五年級上學期（康軒版）史前文化；國立臺灣史前文化博物館', 'draft'),
  ('ch1-cultures-2', 'ch1-cultures', 'mc', 1, '{"q":"會煉鐵、還挖到外來琉璃珠的，是哪一個史前文化？","opts":["長濱文化","卑南文化","十三行文化"],"a":2,"why":"會煉鐵就是金屬器時代，十三行文化（新北八里）挖到煉鐵的遺跡，還有外地來的琉璃珠、銅錢，表示他們會和外地人交換東西。長濱和卑南都還在用石器。"}'::jsonb, '國小社會五年級上學期（康軒版）史前文化；國立臺灣史前文化博物館', 'draft'),
  ('ch1-cultures-3', 'ch1-cultures', 'mc', 1, '{"q":"用石板蓋房子、做精美玉器的，是哪一個史前文化？","opts":["卑南文化","長濱文化","大坌坑文化"],"a":0,"why":"卑南文化在臺東，遺址裡有很多石板棺和石柱，還有做得很漂亮的玉器。長濱文化住山洞、大坌坑文化還沒有石板屋和這麼多玉器。"}'::jsonb, '國小社會五年級上學期（康軒版）史前文化；國立臺灣史前文化博物館', 'draft'),
  ('ch2-fallow-1', 'ch2-fallow', 'tf', 2, '{"q":"一塊田種了幾年後讓它休息，土地的肥力會慢慢回來。","a":true,"why":"作物長大會用掉土裡的養分，一直種，土地會越來越瘦。讓田休息、長草，落葉和草腐爛後變成養分，肥力就慢慢回來了。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('ch2-fallow-2', 'ch2-fallow', 'who', 2, '{"q":"部落的田為什麼要輪流休耕？誰說得對？","says":[{"n":"阿妮","t":"讓土地休息，肥力回來，以後才能一直有收成"},{"n":"大雄","t":"因為大家想休假，不想種田"},{"n":"小美","t":"因為休耕的田看起來比較漂亮"}],"a":0,"why":"輪流休耕是為了讓土地休養，肥力恢復後再種，部落才能一年一年都有收成。這是照顧土地的智慧，不是因為想休假或好看。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('ch2-fallow-3', 'ch2-fallow', 'mc', 1, '{"q":"很多原住民族種的小米，有什麼特點？","opts":["很耐旱，適合種在山坡上","一定要泡在水裡才能長","只能種在海邊沙灘"],"a":0,"why":"小米很耐旱，不用泡在水裡，種在山坡上也長得好，所以很適合住在山區的原住民族。很多部落的祭典也跟著小米播種、收成的時間舉行。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('ch2-hunt-1', 'ch2-hunt', 'multi', 2, '{"q":"部落打獵常有哪些規矩？（可以選很多個）","opts":["有些季節不打獵","不打懷孕的母獸和小動物","不闖進別人的獵場","看到什麼就全部打光"],"a":[0,1,2],"why":"不在動物生小孩的季節打獵、不打懷孕的母獸和小動物，動物才能一直繁衍；不闖別人的獵場，部落之間才不會起衝突。全部打光，以後就沒有獵物了。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('ch2-hunt-2', 'ch2-hunt', 'mc', 2, '{"q":"春天不打獵，主要是為了什麼？","opts":["春天下雨，路太滑","讓母鹿安心生小鹿，鹿群才能延續","春天的鹿肉比較不好吃"],"a":1,"why":"春天是很多動物生小孩的季節。這時候不打獵，母鹿才能平安生下小鹿，鹿群才會一直延續，以後也還有鹿可以打。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('ch2-norms-1', 'ch2-norms', 'tf', 2, '{"q":"部落的規範，很多是從和自然相處的經驗，一代一代累積下來的。","a":true,"why":"祖先在山林裡生活很久，發現怎麼做動物會變少、怎麼做會缺糧，就把經驗變成大家要遵守的規矩，一代一代傳下來。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('ch2-norms-2', 'ch2-norms', 'mc', 2, '{"q":"打到的獵物、收成的小米分給大家，對部落有什麼幫助？","opts":["讓每一家都有得吃，一起度過難關","讓打獵的人以後不用再出門","讓山上的獵物馬上變得更多"],"a":0,"why":"每一年、每一家的收成和打獵不一定一樣好。把食物分給大家，誰家缺糧都有人幫忙，整個部落就能一起度過難關。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('ch2-peoples-1', 'ch2-peoples', 'mc', 1, '{"q":"臺灣原住民族屬於哪一個語族？","opts":["南島語族","日耳曼語族","漢藏語族"],"a":0,"why":"南島語族是說相近語言的一大群民族，從臺灣一直分布到太平洋、印度洋的很多島嶼，像紐西蘭、夏威夷。很多學者認為臺灣可能是南島語族的老家之一。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('ch2-peoples-2', 'ch2-peoples', 'who', 2, '{"q":"關於臺灣的原住民族，誰說得對？","says":[{"n":"小凱","t":"原住民族只有一族，大家說一樣的話"},{"n":"阿妮","t":"政府認定的有 16 族，每一族有自己的語言和祭儀"},{"n":"小玲","t":"原住民族全部都住在海邊"}],"a":1,"why":"臺灣原住民族不是只有一族，目前政府認定有 16 族，像阿美族、泰雅族、排灣族、達悟族，各有自己的語言、服飾和祭典，住的地方有山上也有海邊。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('ch3-entrepot-1', 'ch3-entrepot', 'tf', 2, '{"q":"轉口貿易是把貨先運到一個港口，再轉運到別的地方賣。","a":true,"why":"轉口貿易就是「先運到這裡，再轉運出去」。像荷蘭人把中國的生絲、瓷器先運到大員，再轉運到日本、東南亞和歐洲去賣。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch3-entrepot-2', 'ch3-entrepot', 'mc', 3, '{"q":"大員能成為轉運站，最主要是因為什麼？","opts":["剛好在中國、日本、南洋航線的中間","那裡的東西全部都最便宜","只有大員有港口"],"a":0,"why":"大員剛好在中國、日本、東南亞幾條航線的中間，船從哪裡來都方便停靠、換貨，所以成為轉運站。不是因為東西最便宜，也不是只有它有港口。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch3-entrepot-3', 'ch3-entrepot', 'mc', 1, '{"q":"荷蘭人來到大員，是哪一個組織派來做生意的？","opts":["荷蘭東印度公司","英國的洋行","清朝的水師"],"a":0,"why":"荷蘭東印度公司是一間可以做生意、也有軍隊的大公司，總部在巴達維亞（今天的印尼雅加達），大員是它在東亞做生意的據點。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch3-monsoon-1', 'ch3-monsoon', 'cloze', 2, '{"q":"從大員坐帆船去日本。","text":"往北去日本，最好等{0}吹西南季風時出發；回來時，等{1}吹東北季風。","blanks":[{"opts":["夏天","冬天"],"a":0},{"opts":["夏天","冬天"],"a":1}],"why":"帆船要順風走。夏天吹西南季風，風往東北吹，正好推船往北去日本；冬天吹東北季風，風往西南吹，剛好推船回來。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch3-monsoon-2', 'ch3-monsoon', 'tf', 2, '{"q":"從前的帆船去日本，冬天出發最順。","a":false,"why":"冬天吹的是東北季風，風從日本那個方向吹過來，往日本開就是逆風，帆船走不動。所以去日本要等夏天的西南季風，冬天才是回程的好時機。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch3-sinkan-1', 'ch3-sinkan', 'mc', 1, '{"q":"新港文書是用什麼文字寫的？","opts":["用羅馬字拼寫西拉雅語","漢字","日文假名"],"a":0,"why":"西拉雅族原本沒有文字。荷蘭傳教士用羅馬字母（像英文字母）幫他們把自己的話拼寫出來，這種文字寫成的文件就叫新港文書，不是漢字或日文。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch3-sinkan-2', 'ch3-sinkan', 'tf', 2, '{"q":"荷蘭人離開以後，西拉雅族人還用羅馬字寫土地契約。","a":true,"why":"荷蘭人走了以後，西拉雅族人還繼續用羅馬字寫土地買賣的契約，用了一百多年，所以留下很多新港文書，可以看出這種文字真的融入了生活。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch3-timeline-1', 'ch3-timeline', 'order', 2, '{"q":"把這些事情照發生的先後排好。","steps":["荷蘭人來到大員","西班牙人在基隆蓋城堡","荷蘭人趕走西班牙人","鄭成功讓荷蘭人離開臺灣"],"why":"記住年份就不會排錯：1624 荷蘭人到大員→1626 西班牙人到基隆→1642 荷蘭人把西班牙人趕走→1662 鄭成功讓荷蘭人離開臺灣。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch3-timeline-2', 'ch3-timeline', 'mc', 1, '{"q":"荷蘭人在大員蓋的城堡叫什麼？今天在那裡的是安平古堡。","opts":["熱蘭遮城","聖薩爾瓦多城","紅毛城"],"a":0,"why":"荷蘭人在大員（今天臺南安平）蓋的是熱蘭遮城，就是現在的安平古堡。聖薩爾瓦多城是西班牙人在基隆蓋的；淡水紅毛城最早也是西班牙人蓋的。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch3-timeline-3', 'ch3-timeline', 'mc', 1, '{"q":"西班牙人在北臺灣蓋城堡，主要在哪裡？","opts":["基隆和淡水","臺南和高雄","花蓮和臺東"],"a":0,"why":"西班牙人從菲律賓往北來，先占領北臺灣的基隆，又到淡水，在兩地蓋城堡、傳教。南部的臺南那時是荷蘭人的地盤。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch3-goods-1', 'ch3-goods', 'mc', 1, '{"q":"荷蘭時期，臺灣的鹿皮大多賣到哪裡？","opts":["日本","美國","澳洲"],"a":0,"why":"荷蘭時期臺灣的梅花鹿很多，鹿皮大多賣到日本，日本人拿來做武士的盔甲和衣服。那時候和美國、澳洲還沒有這種貿易。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch3-goods-2', 'ch3-goods', 'who', 2, '{"q":"荷蘭時期每年運走好幾萬張鹿皮，結果會怎樣？誰說得對？","says":[{"n":"阿福","t":"鹿會越來越少"},{"n":"小真","t":"鹿會越來越多"},{"n":"大衛","t":"鹿的數量不會改變"}],"a":0,"why":"每年捕走好幾萬隻鹿，鹿生小鹿的速度追不上被捕的速度，數量就越來越少。後來臺灣的野生梅花鹿幾乎消失，就是這個原因。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch3-goods-3', 'ch3-goods', 'tf', 1, '{"q":"荷蘭人招募從福建來的漢人種甘蔗、做糖。","a":true,"why":"荷蘭人需要很多人手種甘蔗、做糖，就招募對岸福建的漢人渡海來臺灣。糖是荷蘭時期很重要的出口貨。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('ch4-tuntian-1', 'ch4-tuntian', 'mc', 2, '{"q":"「寓兵於農」的兵，平常在做什麼？","opts":["種田，要打仗時再上戰場","一直在練習射箭","在城裡賣東西"],"a":0,"why":"「寓兵於農」就是把兵藏在農民裡：軍隊平常分到各地開墾、種田，自己生產糧食；要打仗的時候再拿起武器上戰場。"}'::jsonb, '國小社會五年級（康軒版）鄭氏時期；文化部《臺灣大百科全書》', 'draft'),
  ('ch4-tuntian-2', 'ch4-tuntian', 'multi', 2, '{"q":"哪些地名是從鄭氏時期軍隊屯田紮營留下來的？（選兩個以上）","opts":["新營","左營","林鳳營","淡水"],"a":[0,1,2],"why":"鄭氏時期軍隊在各地紮營開墾，營區後來變成村莊，名字就留下「營」字，像新營、左營、林鳳營、柳營。淡水是在河口，名字跟水有關，不是軍營。"}'::jsonb, '國小社會五年級（康軒版）鄭氏時期；文化部《臺灣大百科全書》', 'draft'),
  ('ch4-tuntian-3', 'ch4-tuntian', 'tf', 3, '{"q":"軍隊自己種糧食，就不用一直從海上運米來。","a":true,"why":"從海上運米又遠又危險，碰到颱風或敵人就沒糧食。軍隊自己種田，糧食就不用一直靠海運，也順便把很多荒地開成農田。"}'::jsonb, '國小社會五年級（康軒版）鄭氏時期；文化部《臺灣大百科全書》', 'draft'),
  ('ch4-pond-1', 'ch4-pond', 'mc', 2, '{"q":"臺南一帶挖水埤，主要是為了什麼？","opts":["把雨季的水存起來，旱季拿來灌溉","挖成游泳池，讓大家夏天玩水","在港口前面擋住外國的船"],"a":0,"why":"臺南夏天雨很多、冬天很少下雨。挖水埤可以把雨季多出來的水存起來，到了旱季再拿來灌溉，田才不會乾掉。"}'::jsonb, '國小社會五年級（康軒版）鄭氏時期；文化部《臺灣大百科全書》', 'draft'),
  ('ch4-pond-2', 'ch4-pond', 'who', 3, '{"q":"一個地方夏天雨很多、冬天幾乎不下雨，誰的辦法最好？","says":[{"n":"小蓮","t":"挖一個埤，把夏天的水存起來"},{"n":"阿忠","t":"冬天不要種任何東西"},{"n":"小慧","t":"把河填平，田就不會淹水"}],"a":0,"why":"問題是「夏天水太多、冬天水不夠」，最好的辦法就是把夏天的水存起來冬天用，這就是挖水埤的道理。冬天不種會沒收成，把河填平更會淹水。"}'::jsonb, '國小社會五年級（康軒版）鄭氏時期；文化部《臺灣大百科全書》', 'draft'),
  ('ch4-school-1', 'ch4-school', 'mc', 1, '{"q":"被叫做「全臺首學」的是哪裡？","opts":["臺南孔廟","臺北101","熱蘭遮城"],"a":0,"why":"臺南孔廟在 1666 年建好，是臺灣第一座孔廟，旁邊設了學校教讀書，所以叫「全臺首學」，意思是全臺灣第一所學校。"}'::jsonb, '國小社會五年級（康軒版）鄭氏時期；文化部《臺灣大百科全書》', 'draft'),
  ('ch4-school-2', 'ch4-school', 'tf', 1, '{"q":"臺南孔廟是臺灣第一座孔廟。","a":true,"why":"臺南孔廟在鄭氏時期的 1666 年由陳永華建議蓋好，是臺灣第一座孔廟，門口還掛著「全臺首學」的匾額。"}'::jsonb, '國小社會五年級（康軒版）鄭氏時期；文化部《臺灣大百科全書》', 'draft'),
  ('ch4-salt-1', 'ch4-salt', 'mc', 2, '{"q":"陳永華教人「曬鹽」，比原本的「煎鹽」好在哪裡？","opts":["用太陽曬，省下很多柴，鹽也做得更多","曬出來的鹽是甜的，比較好吃","曬鹽不用海水，用河水就可以"],"a":0,"why":"煎鹽要一直燒柴煮海水，很費柴又做得少；曬鹽是把海水引到鹽田讓太陽曬乾，不用燒柴，一次可以做很多。鹽不會變甜，也一定要用海水。"}'::jsonb, '國小社會五年級（康軒版）鄭氏時期；文化部《臺灣大百科全書》', 'draft'),
  ('ch4-salt-2', 'ch4-salt', 'order', 2, '{"q":"排出曬鹽的順序。","steps":["把海水引進鹽田","讓太陽曬，水慢慢蒸發","鹽田裡留下白白的鹽","把鹽收起來"],"why":"曬鹽的道理是讓水跑掉、鹽留下來：先把海水引進鹽田，太陽把水分曬乾，白白的鹽就留在田裡，最後再收起來。"}'::jsonb, '國小社會五年級（康軒版）鄭氏時期；文化部《臺灣大百科全書》', 'draft'),
  ('ch4-people-1', 'ch4-people', 'cat', 1, '{"q":"這些人和哪件事有關？","cats":["趕走荷蘭人","推動教育和曬鹽","攻下澎湖、臺灣歸清朝"],"cards":[{"t":"鄭成功","c":0},{"t":"陳永華","c":1},{"t":"施琅","c":2}],"why":"鄭成功在 1662 年讓荷蘭人離開臺灣；陳永華是鄭家的重要幫手，蓋孔廟辦教育、教人曬鹽；施琅是清朝的將軍，打下澎湖，臺灣後來歸清朝。"}'::jsonb, '國小社會五年級（康軒版）鄭氏時期；文化部《臺灣大百科全書》', 'draft'),
  ('ch4-people-2', 'ch4-people', 'tf', 2, '{"q":"1683 年鄭克塽投降以後，臺灣歸清朝統治。","a":true,"why":"1683 年施琅帶清軍打下澎湖，鄭成功的孫子鄭克塽投降，從此臺灣歸清朝統治，鄭氏時期結束。"}'::jsonb, '國小社會五年級（康軒版）鄭氏時期；文化部《臺灣大百科全書》', 'draft'),
  ('ch4-people-3', 'ch4-people', 'mc', 1, '{"q":"鄭經把臺灣改名叫什麼？","opts":["東寧","大員","福爾摩沙"],"a":0,"why":"鄭成功把臺灣叫「東都」，他的兒子鄭經後來改名叫「東寧」。大員是更早荷蘭時期臺南一帶的名字，福爾摩沙是西方人對臺灣的稱呼。"}'::jsonb, '國小社會五年級（康軒版）鄭氏時期；文化部《臺灣大百科全書》', 'draft'),
  ('ch5-flow-1', 'ch5-flow', 'tf', 2, '{"q":"挖水圳要讓圳道慢慢往低的地方走，水才流得過去。","a":true,"why":"水只會往一樣高或更低的地方流，不會自己往上爬。所以圳道要從高處慢慢往低處挖，水才能一路流到田裡。"}'::jsonb, '國小社會五年級下學期（康軒版）〈清帝國時期臺灣的發展與改變〉；文化部《臺灣大百科全書》「八堡圳」條', 'draft'),
  ('ch5-flow-2', 'ch5-flow', 'mc', 3, '{"q":"八堡圳的圳頭，為什麼開在上游的二水？","opts":["二水比下游的平原高，水才能一路流進田裡","二水的溪水比較甜，種出來的米比較好吃","二水離海最近，挖好的圳道可以順便行船"],"a":0,"why":"水往低處流，所以引水的圳頭一定要比田高。二水在濁水溪上游，地勢比下面的彰化平原高，水才能沿著圳道流進田裡，跟水甜不甜、離海近不近沒關係。"}'::jsonb, '國小社會五年級下學期（康軒版）〈清帝國時期臺灣的發展與改變〉；文化部《臺灣大百科全書》「八堡圳」條', 'draft'),
  ('ch5-flow-3', 'ch5-flow', 'mc', 2, '{"q":"地圖上的等高線越密，表示什麼？","opts":["坡越陡","水越深","人越多"],"a":0,"why":"等高線是把一樣高的地方連起來的線。線越密，表示走一小段路高度就變很多，所以坡越陡；線很疏，表示地比較平。"}'::jsonb, '國小社會五年級下學期（康軒版）〈清帝國時期臺灣的發展與改變〉；文化部《臺灣大百科全書》「八堡圳」條', 'draft'),
  ('ch5-cage-1', 'ch5-cage', 'mc', 2, '{"q":"竹蛇籠是用什麼做的？","opts":["竹子編成長籠子，裡面裝石頭","鐵打成一扇很重的大門","木頭釘成一艘長長的船"],"a":0,"why":"竹蛇籠是用竹子編成長長的籠子，裡面塞滿石頭，一個一個排在河裡，像一條長蛇，可以把溪水導進圳頭，也不容易被沖走。"}'::jsonb, '國小社會五年級下學期（康軒版）〈清帝國時期臺灣的發展與改變〉；文化部《臺灣大百科全書》「八堡圳」條', 'draft'),
  ('ch5-cage-2', 'ch5-cage', 'who', 3, '{"q":"大水來的時候，誰的方法比較不容易被沖壞？","says":[{"n":"阿穆","t":"斜斜地把水導到旁邊"},{"n":"小明","t":"正面蓋一道牆硬擋"},{"n":"阿蓮","t":"什麼都不做"}],"a":0,"why":"大水的力量很大，正面硬擋，全部的力量都打在牆上，很容易被沖垮。斜斜地把水導到旁邊，是順著水的方向，比較省力也比較不會壞。"}'::jsonb, '國小社會五年級下學期（康軒版）〈清帝國時期臺灣的發展與改變〉；文化部《臺灣大百科全書》「八堡圳」條', 'draft'),
  ('ch5-fair-1', 'ch5-fair', 'mc', 3, '{"q":"甲村有 6 塊田、乙村有 4 塊田，一起分 10 份水，怎麼分比較公平？","opts":["甲 6 份、乙 4 份","甲 5 份、乙 5 份","先挖到的全部拿走"],"a":0,"why":"甲村田多、需要的水多，乙村田少、需要的水少。照田的多少分（甲 6、乙 4），每一塊田分到的水一樣多，這才公平。各分 5 份是「平均」，甲村的田反而不夠水。"}'::jsonb, '國小社會五年級下學期（康軒版）〈清帝國時期臺灣的發展與改變〉；文化部《臺灣大百科全書》「八堡圳」條', 'draft'),
  ('ch5-fair-2', 'ch5-fair', 'tf', 2, '{"q":"「平均」分和「公平」分，意思一定一樣。","a":false,"why":"「平均」是每一邊一樣多；「公平」要看每一邊的需要。像田多的村子需要比較多水，照需要分才公平，所以兩個意思不一定一樣。"}'::jsonb, '國小社會五年級下學期（康軒版）〈清帝國時期臺灣的發展與改變〉；文化部《臺灣大百科全書》「八堡圳」條', 'draft'),
  ('ch5-babao-1', 'ch5-babao', 'mc', 1, '{"q":"八堡圳是從哪一條河引水？","opts":["濁水溪","淡水河","曾文溪"],"a":0,"why":"八堡圳在彰化，從濁水溪上游的二水引水，灌溉整個彰化平原。淡水河在北部，曾文溪在臺南，都離彰化很遠。"}'::jsonb, '國小社會五年級下學期（康軒版）〈清帝國時期臺灣的發展與改變〉；文化部《臺灣大百科全書》「八堡圳」條', 'draft'),
  ('ch5-babao-2', 'ch5-babao', 'cloze', 1, '{"q":"八堡圳的故事。","text":"{0}從 1709 年開始找人開圳，前後大約花了{1}才完成。","blanks":[{"opts":["施世榜","劉銘傳","八田與一"],"a":0},{"opts":["十年","一個月","一百年"],"a":0}],"why":"施世榜在 1709 年開始找人開八堡圳，前後大約花了十年才完成（傳說還有林先生教他用竹蛇籠）。劉銘傳是清末的巡撫，八田與一是日治時期蓋嘉南大圳的工程師。"}'::jsonb, '國小社會五年級下學期（康軒版）〈清帝國時期臺灣的發展與改變〉；文化部《臺灣大百科全書》「八堡圳」條', 'draft'),
  ('ch5-babao-3', 'ch5-babao', 'tf', 2, '{"q":"八堡圳到今天還在灌溉彰化的田。","a":true,"why":"八堡圳從清朝開到現在已經三百多年，到今天還在把濁水溪的水送到彰化的田裡，是臺灣很重要的古老水圳。"}'::jsonb, '國小社會五年級下學期（康軒版）〈清帝國時期臺灣的發展與改變〉；文化部《臺灣大百科全書》「八堡圳」條', 'draft'),
  ('ch6-tea-1', 'ch6-tea', 'mc', 2, '{"q":"開港以後，大稻埕變熱鬧，主要因為什麼？","opts":["茶葉大量出口，茶行、洋行都聚在這裡","那裡蓋了全臺第一座孔廟","那裡是荷蘭人的城堡"],"a":0,"why":"清末開港以後，北部山上種的茶大量賣到國外。茶行、洋行都聚到淡水河邊的大稻埕加工、出貨，人和錢都來了，大稻埕就變得很熱鬧。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch6-tea-2', 'ch6-tea', 'mc', 1, '{"q":"清末賣到美國很受歡迎的「福爾摩沙茶」是哪一種？","opts":["烏龍茶","紅豆湯","咖啡"],"a":0,"why":"清末臺灣北部的烏龍茶賣到美國很受歡迎，外國人叫它「福爾摩沙烏龍茶」（Formosa Oolong）。紅豆湯、咖啡都不是當時有名的出口茶。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch6-tea-3', 'ch6-tea', 'order', 3, '{"q":"大稻埕的茶怎麼賣到國外？排出順序。","steps":["山上的茶農採茶","茶送到大稻埕的茶行加工","從淡水港上大船","運到國外賣"],"why":"茶要先在山上採下來，送到大稻埕的茶行烘焙、包裝，再從淡水港裝上大船運到國外。照「採→加工→上船→賣」的順序想就對了。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch6-rail-1', 'ch6-rail', 'tf', 2, '{"q":"鐵路蓋好以後，人和貨物可以比以前更快運到遠方。","a":true,"why":"以前靠走路、牛車或渡河，遇到河水太深就過不去。火車一次能載很多人和貨，跑得又快，有橋就能過河，所以運到遠方快很多。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch6-rail-2', 'ch6-rail', 'mc', 1, '{"q":"基隆到臺北之間的山太陡，火車怎麼過去？","opts":["挖隧道穿過山（獅球嶺隧道）","用纜車把火車吊過山頭","把鐵路繞到海上的橋走"],"a":0,"why":"基隆和臺北之間有獅球嶺擋著，坡太陡火車爬不上去，所以劉銘傳時代挖了一條隧道穿過去，就是臺灣第一座鐵路隧道「獅球嶺隧道」。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch6-rail-3', 'ch6-rail', 'mc', 1, '{"q":"清末劉銘傳時代的火車頭，現在還保存在博物館的是哪一輛？","opts":["騰雲號","太魯閣號","普悠瑪號"],"a":0,"why":"騰雲號是劉銘傳時代從國外買來的蒸汽火車頭，現在保存在臺北的國立臺灣博物館。太魯閣號、普悠瑪號是現在才有的新式列車。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch6-mackay-1', 'ch6-mackay', 'multi', 2, '{"q":"馬偕在淡水做了哪些事？（選兩個以上）","opts":["學會說臺語","幫人看病、拔牙","辦學堂教新知識","蓋了全臺首學孔廟"],"a":[0,1,2],"why":"馬偕到淡水後先學會說臺語，幫人看病、拔牙，又辦學堂教新知識。全臺首學的孔廟是鄭氏時期在臺南蓋的，跟馬偕沒關係。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch6-mackay-2', 'ch6-mackay', 'mc', 1, '{"q":"馬偕是從哪一個國家來的？","opts":["加拿大","荷蘭","日本"],"a":0,"why":"馬偕是從加拿大來的傳教士兼醫生，1872 年到淡水，在臺灣住了將近三十年，最後也葬在淡水。荷蘭人和日本人是不同時期來臺灣的。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch6-ports-1', 'ch6-ports', 'cat', 2, '{"q":"哪些是清末臺灣的三大出口品？","cats":["三大出口品","不是"],"cards":[{"t":"茶","c":0},{"t":"樟腦","c":0},{"t":"糖","c":0},{"t":"電視機","c":1}],"why":"清末臺灣賣到國外最多的三樣東西是茶、樟腦和糖，叫「三大出口品」。電視機要到一百年後才有，當然不是。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch6-ports-2', 'ch6-ports', 'multi', 1, '{"q":"清末開港，臺灣開放了哪些港口？（選兩個以上）","opts":["淡水","基隆","安平","日月潭"],"a":[0,1,2],"why":"清末開放的四個港口是北部的淡水、基隆和南部的安平、打狗（高雄）。日月潭是在山裡的湖，不可能當海港。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch6-ports-3', 'ch6-ports', 'tf', 1, '{"q":"洋行是外國商人開的貿易公司。","a":true,"why":"洋行是外國商人開的貿易公司。他們向臺灣人買茶、樟腦、糖運到國外賣，也把外國的貨（像鴉片、布料）運進臺灣。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch6-liu-1', 'ch6-liu', 'mc', 1, '{"q":"臺灣建省後的第一任巡撫是誰？","opts":["劉銘傳","鄭成功","馬偕"],"a":0,"why":"1885 年臺灣建省，劉銘傳當第一任巡撫，推動鐵路、電報、郵政和新式學堂，讓臺灣變得比較現代化。鄭成功、馬偕都是別的時期、別的身分。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch6-liu-2', 'ch6-liu', 'multi', 2, '{"q":"劉銘傳推動了哪些建設？（選兩個以上）","opts":["鋪鐵路","架電報線","設郵政","蓋高鐵"],"a":[0,1,2],"why":"劉銘傳鋪了基隆到新竹的鐵路、架電報線、設郵政，讓交通和通訊變快。高鐵是 2007 年才通車的，和清末的劉銘傳無關。"}'::jsonb, '國小社會五年級下學期（康軒版）開港通商與建設；文化部《臺灣大百科全書》', 'draft'),
  ('ch7-rotation-1', 'ch7-rotation', 'mc', 2, '{"q":"嘉南大圳的「三年輪作」，把田分成幾區輪流種？","opts":["三區","兩區","十區"],"a":0,"why":"嘉南大圳的水不夠讓所有田同時種稻，所以把田分成三區，每區每年輪流種水稻、甘蔗和雜作，三年輪一圈。"}'::jsonb, '國小社會五年級下學期（康軒版）日治時期的臺灣；文化部《臺灣大百科全書》', 'draft'),
  ('ch7-rotation-2', 'ch7-rotation', 'who', 3, '{"q":"為什麼嘉南平原要三年輪作？誰說得對？","says":[{"n":"阿雄","t":"水不夠讓全部的田同時種稻，輪流才分得夠"},{"n":"小雅","t":"因為農民喜歡每年換種東西"},{"n":"阿德","t":"因為甘蔗不需要土"}],"a":0,"why":"水庫一年放得出的水有限，不夠全部的田同時種很需要水的稻子。分區輪流種，水才夠分，每一區也都輪得到種稻。跟喜不喜歡換、甘蔗要不要土無關。"}'::jsonb, '國小社會五年級下學期（康軒版）日治時期的臺灣；文化部《臺灣大百科全書》', 'draft'),
  ('ch7-railway-1', 'ch7-railway', 'mc', 1, '{"q":"縱貫鐵路全線通車，是從哪裡到哪裡？","opts":["基隆到高雄","臺北到宜蘭","花蓮到臺東"],"a":0,"why":"縱貫鐵路在 1908 年全線通車，從北部的基隆一路通到南部的高雄（打狗），把臺灣西部南北連起來。"}'::jsonb, '國小社會五年級下學期（康軒版）日治時期的臺灣；文化部《臺灣大百科全書》', 'draft'),
  ('ch7-railway-2', 'ch7-railway', 'tf', 2, '{"q":"縱貫鐵路通車後，南北來往從好多天變成大約一天。","a":true,"why":"以前南北往來要走好多天，縱貫鐵路通車後坐火車大約一天就到，人、米、糖都能很快運到港口。"}'::jsonb, '國小社會五年級下學期（康軒版）日治時期的臺灣；文化部《臺灣大百科全書》', 'draft'),
  ('ch7-twosides-1', 'ch7-twosides', 'who', 3, '{"q":"說到日治時期的建設，誰的看法比較完整？","says":[{"n":"小婷","t":"建設帶來進步，也要看到臺灣人受到不平等對待"},{"n":"阿凱","t":"全部都是好的，沒有壞處"},{"n":"小宇","t":"全部都是壞的，什麼都沒改變"}],"a":0,"why":"看歷史要看兩面：日治時期的鐵路、水圳、學校讓臺灣進步；但重要的事多由日本人決定，臺灣人受到不平等對待。只說全好或全壞，都不完整。"}'::jsonb, '國小社會五年級下學期（康軒版）日治時期的臺灣；文化部《臺灣大百科全書》', 'draft'),
  ('ch7-twosides-2', 'ch7-twosides', 'mc', 2, '{"q":"日治時期，臺灣孩子讀的學校叫什麼？","opts":["公學校","小學校","書院"],"a":0,"why":"日治時期，臺灣孩子讀「公學校」，日本孩子讀「小學校」，兩邊的設備和升學機會不一樣，這就是不平等的地方。書院是清朝時讀書的地方。"}'::jsonb, '國小社會五年級下學期（康軒版）日治時期的臺灣；文化部《臺灣大百科全書》', 'draft'),
  ('ch7-twosides-3', 'ch7-twosides', 'cloze', 1, '{"q":"日治時期。","text":"從{0}年到{1}年，臺灣由日本統治。","blanks":[{"opts":["1895","1683","1945"],"a":0},{"opts":["1945","1895","1662"],"a":0}],"why":"1895 年清朝打輸甲午戰爭，把臺灣割給日本；1945 年日本在第二次世界大戰戰敗，結束統治。所以日治時期是 1895 到 1945 年，大約 50 年。"}'::jsonb, '國小社會五年級下學期（康軒版）日治時期的臺灣；文化部《臺灣大百科全書》', 'draft'),
  ('ch7-canal-1', 'ch7-canal', 'mc', 1, '{"q":"設計烏山頭水庫和嘉南大圳的工程師是誰？","opts":["八田與一","劉銘傳","施世榜"],"a":0,"why":"八田與一是日本的水利工程師，設計了烏山頭水庫和嘉南大圳，1930 年完工，讓嘉南平原的田有水灌溉。劉銘傳是清末巡撫，施世榜開的是八堡圳。"}'::jsonb, '國小社會五年級下學期（康軒版）日治時期的臺灣；文化部《臺灣大百科全書》', 'draft'),
  ('ch7-canal-2', 'ch7-canal', 'mc', 2, '{"q":"嘉南大圳完成以後，「看天田」有什麼改變？","opts":["有水圳引水，可以穩定耕種","全部改蓋房子","變成鹽田"],"a":0,"why":"「看天田」沒有水圳，只能等老天下雨。嘉南大圳把水送到田裡以後，不下雨也有水，就能穩定耕種，收成變好很多。"}'::jsonb, '國小社會五年級下學期（康軒版）日治時期的臺灣；文化部《臺灣大百科全書》', 'draft'),
  ('ch7-canal-3', 'ch7-canal', 'tf', 2, '{"q":"「看天田」是只能靠下雨灌溉的田。","a":true,"why":"「看天田」意思是要看老天爺臉色的田：沒有水圳灌溉，只能靠下雨，雨不來作物就種不起來。"}'::jsonb, '國小社會五年級下學期（康軒版）日治時期的臺灣；文化部《臺灣大百科全書》', 'draft'),
  ('ch7-sunmoon-1', 'ch7-sunmoon', 'mc', 2, '{"q":"日月潭發電工程讓湖水升高，住在那裡的哪一族失去了家園？","opts":["邵族","達悟族","阿美族"],"a":0,"why":"日月潭一帶原本是邵族的家。日治時期蓋發電工程，把濁水溪的水引進日月潭，湖水變高，淹掉了邵族的部落和田地。達悟族在蘭嶼，阿美族多在東部。"}'::jsonb, '國小社會五年級下學期（康軒版）日治時期的臺灣；文化部《臺灣大百科全書》', 'draft'),
  ('ch7-sunmoon-2', 'ch7-sunmoon', 'tf', 1, '{"q":"日月潭發電所是用水從高處沖下來的力量發電。","a":true,"why":"把日月潭的水從高處引下山，水往下沖的力量很大，可以轉動發電機，這就是水力發電。所以要有高低差，水才能發電。"}'::jsonb, '國小社會五年級下學期（康軒版）日治時期的臺灣；文化部《臺灣大百科全書》', 'draft'),
  ('end-ten-1', 'end-ten', 'cat', 2, '{"q":"十大建設是哪一類？","cats":["交通","重工業","能源"],"cards":[{"t":"中山高速公路","c":0},{"t":"北迴鐵路","c":0},{"t":"大煉鋼廠","c":1},{"t":"核能發電廠","c":2}],"why":"想想每一項是做什麼的：高速公路、鐵路讓人和貨跑得快，是「交通」；煉鋼廠做鋼鐵這種很重的材料，是「重工業」；核能發電廠產生電，是「能源」。"}'::jsonb, '國小社會（康軒版）戰後臺灣的經濟發展、民主社會與公民參與單元；文化部《臺灣大百科全書》「十大建設」條', 'draft'),
  ('end-ten-2', 'end-ten', 'mc', 1, '{"q":"十大建設是在什麼時候推動的？","opts":["1970 年代","1890 年代","2020 年代"],"a":0,"why":"十大建設是政府在 1970 年代推動的十項大工程，像中山高速公路、桃園機場，讓臺灣經濟起飛。1890 年代是清末，2020 年代是現在。"}'::jsonb, '國小社會（康軒版）戰後臺灣的經濟發展、民主社會與公民參與單元；文化部《臺灣大百科全書》「十大建設」條', 'draft'),
  ('end-ten-3', 'end-ten', 'tf', 2, '{"q":"十大建設裡，交通建設最多。","a":true,"why":"十項裡有六項是交通：中山高速公路、北迴鐵路、鐵路電氣化、桃園國際機場、臺中港、蘇澳港。另外是三項重工業和一項能源，所以交通最多。"}'::jsonb, '國小社會（康軒版）戰後臺灣的經濟發展、民主社會與公民參與單元；文化部《臺灣大百科全書》「十大建設」條', 'draft'),
  ('end-hsr-1', 'end-hsr', 'mc', 1, '{"q":"臺灣高鐵在哪一年通車？","opts":["2007 年","1908 年","1979 年"],"a":0,"why":"臺灣高鐵在 2007 年通車。1908 年是縱貫鐵路全線通車，1979 年是桃園機場（當時叫中正機場）啟用，別把年份搞混了。"}'::jsonb, '國小社會（康軒版）戰後臺灣的經濟發展、民主社會與公民參與單元；文化部《臺灣大百科全書》「十大建設」條', 'draft'),
  ('end-hsr-2', 'end-hsr', 'mc', 2, '{"q":"「一日生活圈」是什麼意思？","opts":["南北來往很快，一天就能來回","每天只能出門一次","一天要繞臺灣一圈"],"a":0,"why":"一日生活圈是說交通很快，早上出門、晚上就能回家。高鐵讓臺北到高雄最快大約一個半小時，南北一天就能來回。"}'::jsonb, '國小社會（康軒版）戰後臺灣的經濟發展、民主社會與公民參與單元；文化部《臺灣大百科全書》「十大建設」條', 'draft'),
  ('end-hsr-3', 'end-hsr', 'order', 3, '{"q":"把這些交通建設，照通車或完成的先後排好。","steps":["劉銘傳的鐵路（基隆到臺北）","縱貫鐵路（基隆到高雄）","中山高速公路","臺灣高鐵"],"why":"照年份排：1891 劉銘傳的基隆到臺北鐵路→1908 縱貫鐵路→1978 中山高速公路全線通車→2007 臺灣高鐵。交通工具越來越快。"}'::jsonb, '國小社會（康軒版）戰後臺灣的經濟發展、民主社會與公民參與單元；文化部《臺灣大百科全書》「十大建設」條', 'draft'),
  ('end-minority-1', 'end-minority', 'who', 2, '{"q":"社區開會投票時，誰的做法比較好？","says":[{"n":"小安","t":"先好好討論，也聽聽少數人的意見"},{"n":"阿強","t":"票多的就贏，不用管別人"},{"n":"小莉","t":"誰最大聲就聽誰的"}],"a":0,"why":"投票時票多的贏，這叫多數決，是公平的規則；但投票前先好好討論、聽聽少數人的想法，常能找到更多人都接受的辦法。比大聲、不管別人都不對。"}'::jsonb, '國小社會（康軒版）戰後臺灣的經濟發展、民主社會與公民參與單元；文化部《臺灣大百科全書》「十大建設」條', 'draft'),
  ('end-minority-2', 'end-minority', 'tf', 1, '{"q":"民主社會裡，大家可以用投票表達意見。","a":true,"why":"民主社會裡，每個人都可以用投票表達自己的意見，選出代表或決定事情。投票前好好討論，大家更能了解彼此的想法。"}'::jsonb, '國小社會（康軒版）戰後臺灣的經濟發展、民主社會與公民參與單元；文化部《臺灣大百科全書》「十大建設」條', 'draft'),
  ('end-minority-3', 'end-minority', 'multi', 2, '{"q":"小朋友可以怎麼參與社區或學校的公共事務？（選兩個以上）","opts":["在班會上發言","提出建議","參加投票","偷偷破壞公物"],"a":[0,1,2],"why":"公民參與就是用正當的方法讓大家聽到你的意見：在班會上發言、提出建議、參加投票都是。偷偷破壞公物是違法又傷害大家的行為。"}'::jsonb, '國小社會（康軒版）戰後臺灣的經濟發展、民主社會與公民參與單元；文化部《臺灣大百科全書》「十大建設」條', 'draft'),
  ('town-law-1', 'town-law', 'mc', 2, '{"q":"四種規範裡，哪一種違反了會被國家處罰？","opts":["法律","道德","風俗"],"a":0,"why":"法律是國家訂的，有強制力，違反了會被罰錢或關。道德、風俗不是國家訂的，做不到不會被處罰，但別人可能會覺得不好。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('town-law-2', 'town-law', 'mc', 3, '{"q":"鄰居半夜還用大喇叭唱歌，吵到大家睡不著，可以請誰來處理？","opts":["環保局或警察","郵差","老師"],"a":0,"why":"晚上太吵違反《噪音管制法》，環保局可以來測音量，警察也能來勸導或開罰。郵差和老師沒有處理噪音的權力。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-law-3', 'town-law', 'cat', 2, '{"q":"這些事屬於哪一種規範？","cats":["法律","道德","風俗","宗教"],"cards":[{"t":"半夜太吵會被罰","c":0},{"t":"公車上讓座給長輩","c":1},{"t":"中秋節吃月餅、賞月","c":2},{"t":"進廟不踩門檻","c":3}],"why":"分辨的方法：會被國家處罰的是法律（半夜太吵）；心裡覺得應該做的是道德（讓座）；從以前傳下來的節日習慣是風俗（中秋賞月）；信仰裡的規矩是宗教規範（不踩廟的門檻）。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('town-moral-1', 'town-moral', 'tf', 2, '{"q":"在公車上不讓座，會被警察開罰單。","a":false,"why":"讓座是道德，不是法律。不讓座不會被警察開罰單，但大家可能會覺得你不體貼。道德是靠自己願意去做。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('town-moral-2', 'town-moral', 'who', 2, '{"q":"看到長輩站在公車上，誰的做法最好？","says":[{"n":"小雯","t":"有禮貌地讓座，或請別人讓座"},{"n":"阿哲","t":"打電話叫警察"},{"n":"小可","t":"在網路上罵坐著的人"}],"a":0,"why":"道德靠自己自動去做，或是好好地提醒別人。有禮貌地讓座或請別人讓座最好；叫警察沒有用（讓座不是法律），在網路上罵人更不對。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('town-moral-3', 'town-moral', 'mc', 1, '{"q":"「看到別人需要幫忙，覺得應該幫忙」，這是哪一種規範？","opts":["道德","法律","宗教"],"a":0,"why":"「覺得應該幫忙」是心裡判斷對錯、自動想去做的事，這就是道德。法律是國家規定、不做會被罰；宗教規範是信仰裡的規矩。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('town-custom-1', 'town-custom', 'tf', 1, '{"q":"中秋節團圓、吃月餅，是從以前一直傳下來的風俗。","a":true,"why":"中秋節團圓、吃月餅、賞月，是大家一年一年傳下來的習慣，這就叫風俗。風俗不是法律，但很多人很重視。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('town-custom-2', 'town-custom', 'mc', 2, '{"q":"過年發紅包、端午節划龍舟，屬於哪一種規範？","opts":["風俗","法律","宗教"],"a":0,"why":"過年發紅包、端午划龍舟，都是過節時大家從以前傳下來的習慣，屬於風俗。沒有法律規定一定要做，也不是對神明的宗教規矩。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('town-custom-3', 'town-custom', 'who', 2, '{"q":"中秋節沒辦法回家團圓，會怎麼樣？誰說得對？","says":[{"n":"阿公","t":"不會被處罰，但很多人很重視團圓"},{"n":"小雯","t":"會被罰錢"},{"n":"阿明","t":"會被警察抓"}],"a":0,"why":"團圓是風俗，不是法律，所以做不到不會被罰錢，也不會被警察抓。只是很多人很重視，會覺得可惜，可以打電話或視訊團圓。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('town-religion-1', 'town-religion', 'mc', 2, '{"q":"參觀廟宇時不踩門檻、對神像拍照先問廟方，這屬於哪一種規範？","opts":["宗教規範","法律","風俗"],"a":0,"why":"不踩門檻、拍神像前先問廟方，是對神明表示尊重的規矩，屬於宗教規範。信的人自己遵守，去參觀的人也要尊重。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('town-religion-2', 'town-religion', 'who', 3, '{"q":"外國遊客在廟裡開閃光燈拍神像，誰的做法最好？","says":[{"n":"阿嬤","t":"好好告訴他廟裡的規矩"},{"n":"阿凱","t":"打 110 請警察抓他"},{"n":"小莉","t":"大聲罵他沒禮貌"}],"a":0,"why":"開閃光燈拍神像違反的是宗教規範，不是法律，所以不用叫警察。外國遊客可能不知道，好好告訴他規矩最好；大聲罵人反而不禮貌。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('town-kids-1', 'town-kids', 'tf', 2, '{"q":"幫爸爸買酒的話，未滿 18 歲也可以買。","a":false,"why":"法律規定店家不能把酒賣給未滿 18 歲的人，不管是自己要喝還是幫大人買都不行，這是為了保護兒童和少年。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-kids-2', 'town-kids', 'cloze', 2, '{"q":"保護兒童和少年的法律。","text":"未滿{0}歲的人不能喝酒，菸更嚴格，未滿{1}歲都不行。","blanks":[{"opts":["18","12","15"],"a":0},{"opts":["20","16","18"],"a":0}],"why":"酒：《兒童及少年福利與權益保障法》規定未滿 18 歲不能喝。菸更嚴格：《菸害防制法》規定未滿 20 歲都不能吸菸。所以答案是 18 和 20。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-kids-3', 'town-kids', 'mc', 2, '{"q":"遊戲盒子上標「輔 15」，意思是什麼？","opts":["未滿 15 歲不適合玩","要玩 15 個小時","15 元就可以買"],"a":0,"why":"遊戲和影片有分級，「輔 15」表示內容比較不適合小孩，未滿 15 歲的人不適合玩或看。上面的數字是年齡，不是時間或價錢。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-work-1', 'town-work', 'mc', 2, '{"q":"依照勞動基準法，幾歲以下原則上不能被僱用工作？","opts":["未滿 15 歲","未滿 10 歲","未滿 20 歲"],"a":0,"why":"《勞動基準法》規定，未滿 15 歲的人原則上不能被僱用去工作，讓孩子好好讀書、長大。15 歲以上打工也要有爸媽同意。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-work-2', 'town-work', 'who', 3, '{"q":"14 歲的小雯想去飲料店打工，誰的建議最好？","says":[{"n":"姊姊","t":"先不要去，滿 15 歲、爸媽同意後再找合法的打工"},{"n":"阿傑","t":"偷偷去，不要讓人知道"},{"n":"老闆","t":"不用付錢，當作幫忙就好"}],"a":0,"why":"14 歲還沒滿 15 歲，法律原則上不能被僱用，老闆僱用會被罰。等滿 15 歲、爸媽同意後再找合法的打工最好。偷偷去或不給錢都是不對的。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-fraud-1', 'town-fraud', 'multi', 2, '{"q":"網路賣東西，哪些是詐騙常見的破綻？（選兩個以上）","opts":["價錢便宜得不合理","不能面交、一定要先匯款","一直催你快一點","有很多人留下好評、可以面交"],"a":[0,1,2],"why":"詐騙常見的破綻有三個：價錢便宜得不合理、不讓你看貨就要先匯款、一直催你快點決定。可以面交、看到東西再付錢，反而比較安全。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-fraud-2', 'town-fraud', 'mc', 1, '{"q":"懷疑碰到詐騙，可以打哪一個電話問？","opts":["165 反詐騙專線","119","1999 生活熱線以外都不能打"],"a":0,"why":"165 是警政署的反詐騙諮詢專線，懷疑被騙時可以打去問。119 是火災和救護車；1999 是各縣市的生活熱線，不是專門處理詐騙。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-fraud-3', 'town-fraud', 'tf', 2, '{"q":"別人說要幫你處理帳戶，就可以把銀行密碼給他。","a":false,"why":"銀行帳號的密碼只有自己能知道，任何人說要「幫你處理」都可能是詐騙。密碼一給出去，帳戶裡的錢可能馬上被領光。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-privacy-1', 'town-privacy', 'mc', 2, '{"q":"同學要把有你的照片放上網，還寫出學校和全名，你不同意。依照法律，應該怎麼做？","opts":["請他先拿掉，問過大家同意再放","沒關係，大家都這樣","也放他的照片報復"],"a":0,"why":"每個人都有肖像權（自己的臉）和隱私權（學校、全名這些個人資料）。你不同意，同學就應該先拿掉，問過大家同意再放。說大家都這樣或報復都不對。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-privacy-2', 'town-privacy', 'tf', 1, '{"q":"別人的臉和個人資料受到法律保護，不能沒問過就公開。","a":true,"why":"每個人的臉受「肖像權」保護，名字、住址、學校這些個人資料受「隱私權」保護，法律規定不能沒問過就公開。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-copy-1', 'town-copy', 'mc', 2, '{"q":"做報告用了網路上別人拍的照片，應該怎麼做？","opts":["寫清楚作者和出處","把作者的名字修掉","說是自己拍的"],"a":0,"why":"照片是拍的人的作品，受《著作權法》保護。做報告可以「合理引用」，但一定要寫清楚作者和出處；修掉作者名字或說是自己拍的，都是侵權。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-copy-2', 'town-copy', 'tf', 2, '{"q":"把別人的照片印很多張拿去賣，只要寫出處就沒問題。","a":false,"why":"寫出處只能讓做報告、上課這類「合理使用」變得正當。把別人的照片印來賣錢，已經是拿別人的作品賺錢，就算寫了出處也侵害著作權。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('isles-pacific-1', 'isles-pacific', 'cat', 1, '{"q":"這些島在哪一片海上？","cats":["太平洋","臺灣海峽"],"cards":[{"t":"龜山島","c":0},{"t":"綠島","c":0},{"t":"蘭嶼","c":0},{"t":"澎湖","c":1},{"t":"小琉球","c":1}],"why":"看島在臺灣的哪一邊：東邊的龜山島、綠島、蘭嶼在太平洋；西邊的澎湖、西南邊的小琉球在臺灣海峽裡。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣的離島', 'draft'),
  ('isles-pacific-2', 'isles-pacific', 'mc', 2, '{"q":"蘭嶼是哪一族的家？","opts":["達悟族","邵族","西拉雅族"],"a":0,"why":"蘭嶼是達悟族的家，他們會做彩色的拼板舟，每年飛魚季出海捕飛魚。邵族住在日月潭，西拉雅族在臺南一帶。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣的離島', 'draft'),
  ('isles-pacific-3', 'isles-pacific', 'tf', 1, '{"q":"從宜蘭頭城的海邊，看得到龜山島。","a":true,"why":"龜山島就在宜蘭頭城外面的太平洋上，形狀像一隻浮在海上的烏龜，從頭城的海邊看得很清楚，是宜蘭的地標。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣的離島', 'draft'),
  ('isles-strait-1', 'isles-strait', 'mc', 1, '{"q":"澎湖群島在臺灣本島的哪一邊？","opts":["西邊的臺灣海峽","東邊的太平洋","北邊的東海"],"a":0,"why":"澎湖群島在臺灣本島西邊的臺灣海峽中間，由九十多座小島組成。東邊的太平洋上是綠島、蘭嶼。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣的離島', 'draft'),
  ('isles-strait-2', 'isles-strait', 'mc', 2, '{"q":"澎湖人用咾咕石堆成矮牆圍住菜園（菜宅），主要是為了擋什麼？","opts":["冬天強勁的東北季風","海裡的鯊魚","夏天的大太陽"],"a":0,"why":"澎湖冬天的東北季風又強又冷，菜很容易被吹壞。澎湖人用咾咕石堆成矮牆把菜園圍起來（叫菜宅），就是為了擋風。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣的離島', 'draft'),
  ('isles-strait-3', 'isles-strait', 'tf', 1, '{"q":"小琉球是一座珊瑚礁島。","a":true,"why":"小琉球是由很久以前的珊瑚礁慢慢升起變成的島，是臺灣附近唯一的珊瑚礁島，所以海邊有很多珊瑚礁岩和洞穴。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣的離島', 'draft'),
  ('isles-near-1', 'isles-near', 'mc', 1, '{"q":"金門離哪裡比較近？","opts":["中國大陸","臺灣本島","菲律賓"],"a":0,"why":"金門就在中國大陸廈門的對面，坐船很快就到；離臺灣本島反而要過整個臺灣海峽，坐飛機要快一個小時。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣的離島', 'draft'),
  ('isles-near-2', 'isles-near', 'who', 2, '{"q":"關於馬祖，誰說得對？","says":[{"n":"小安","t":"在臺灣西北邊，靠近中國大陸"},{"n":"阿美","t":"在臺灣東邊的太平洋上"},{"n":"小傑","t":"在臺灣南邊的巴士海峽"}],"a":0,"why":"馬祖在臺灣的西北方，靠近中國大陸的福州（閩江口）。東邊太平洋上的是綠島、蘭嶼，南邊的巴士海峽在臺灣和菲律賓中間。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣的離島', 'draft'),
  ('sky-neighbors-1', 'sky-neighbors', 'cloze', 1, '{"q":"臺灣四周的海。","text":"臺灣和中國大陸中間是{0}，和菲律賓中間是{1}。","blanks":[{"opts":["臺灣海峽","巴士海峽"],"a":0},{"opts":["臺灣海峽","巴士海峽"],"a":1}],"why":"臺灣西邊、和中國大陸中間的是臺灣海峽；南邊、和菲律賓中間的是巴士海峽。記法：西臺灣、南巴士。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣與世界', 'draft'),
  ('sky-neighbors-2', 'sky-neighbors', 'mc', 2, '{"q":"從臺灣往北邊飛，下面這些國家裡最可能到的是哪一個？","opts":["韓國","菲律賓","澳洲"],"a":0,"why":"從臺灣往北，會經過琉球、日本，再往北就是韓國。菲律賓在臺灣南邊，澳洲更遠、在南半球，都要往南飛。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣與世界', 'draft'),
  ('sky-hub-1', 'sky-hub', 'tf', 2, '{"q":"很多日本、韓國飛往東南亞的飛機，會經過臺灣附近的天空。","a":true,"why":"臺灣剛好在東北亞（日本、韓國）和東南亞（菲律賓、越南、泰國）的中間，從北往南飛的飛機很多都會經過臺灣附近，像一個中點站。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣與世界', 'draft'),
  ('sky-hub-2', 'sky-hub', 'mc', 3, '{"q":"為什麼說臺灣是進出亞洲的「門戶」？","opts":["位在東北亞和東南亞航線的中間","臺灣是亞洲最大的國家","臺灣在亞洲的最北邊"],"a":0,"why":"臺灣在東北亞和東南亞航線的中間，飛機、船進出亞洲都很方便經過這裡，所以說是「門戶」。臺灣不是亞洲最大，也不在最北邊。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣與世界', 'draft'),
  ('sky-world-1', 'sky-world', 'multi', 1, '{"q":"下面哪些是世界三大洋？（選三個）","opts":["太平洋","大西洋","印度洋","臺灣海峽"],"a":[0,1,2],"why":"世界三大洋是太平洋、大西洋、印度洋，其中太平洋最大。臺灣海峽只是兩塊陸地中間比較窄的海，不是大洋。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣與世界', 'draft'),
  ('sky-world-2', 'sky-world', 'mc', 2, '{"q":"從臺灣坐船要去歐洲，通常會經過哪一片大洋？","opts":["印度洋","北冰洋","大西洋的北邊"],"a":0,"why":"從臺灣去歐洲的船會往西南走，經過麻六甲海峽，再穿過整個印度洋，然後才到歐洲。北冰洋太冷、太遠，大西洋的北邊方向也不對。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣與世界', 'draft'),
  ('sky-world-3', 'sky-world', 'tf', 1, '{"q":"從臺灣往東橫越太平洋，可以到美洲。","a":true,"why":"臺灣東邊就是太平洋，一直往東越過這片大洋，另一邊就是美洲（像美國、加拿大）。所以往東橫越太平洋可以到美洲。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣與世界', 'draft'),
  ('post-care-1', 'post-care', 'mc', 2, '{"q":"去太魯閣的落石區，應該怎麼做？","opts":["戴安全帽、不停留","在峭壁下野餐","撿大理石帶回家"],"a":0,"why":"太魯閣峽谷的山壁很陡，常常會掉石頭，經過落石區要戴安全帽、快速通過，不能停下來野餐。國家公園的石頭也是大家的，不能帶回家。"}'::jsonb, '國小社會（康軒版）家鄉與臺灣的觀光；各國家公園管理處公開資料', 'draft'),
  ('post-care-2', 'post-care', 'multi', 2, '{"q":"到日月潭玩，哪些做法對環境比較好？（選兩個以上）","opts":["搭公車或騎腳踏車","自己的垃圾帶走","少用一次性餐具","把垃圾丟進湖裡"],"a":[0,1,2],"why":"搭公車、騎腳踏車能少排廢氣；把垃圾帶走、少用一次性餐具，湖邊就不會髒。把垃圾丟進湖裡會汙染湖水，傷害魚和環境。"}'::jsonb, '國小社會（康軒版）家鄉與臺灣的觀光；各國家公園管理處公開資料', 'draft'),
  ('post-care-3', 'post-care', 'who', 3, '{"q":"颱風天快到了，大家想去清水斷崖。誰的想法最安全？","says":[{"n":"小雯","t":"颱風天不要上山，出發前看路況"},{"n":"阿凱","t":"去斷崖邊看大浪最刺激"},{"n":"小宇","t":"開快一點，趕在颱風前衝過去"}],"a":0,"why":"颱風天山區容易坍方、落石，海邊也有大浪，非常危險。最安全的做法是不要出門上山，出發前先查路況。看大浪或趕路衝過去都可能出事。"}'::jsonb, '國小社會（康軒版）家鄉與臺灣的觀光；各國家公園管理處公開資料', 'draft'),
  ('post-local-1', 'post-local', 'mc', 2, '{"q":"新竹新埔曬柿餅，靠的是秋冬哪一種風？","opts":["九降風（又乾又強的東北季風）","夏天又濕又熱的西南季風","夏秋常常帶來大雨的颱風"],"a":0,"why":"秋冬新竹吹九降風，是又乾又強的東北季風，吹得柿子很快變乾，最適合做柿餅。夏天的西南季風又濕又熱，颱風帶雨，都不適合曬柿餅。"}'::jsonb, '國小社會（康軒版）家鄉與臺灣的觀光；各國家公園管理處公開資料', 'draft'),
  ('post-local-2', 'post-local', 'tf', 1, '{"q":"新埔是客家庄，曬柿餅是當地傳下來的產業。","a":true,"why":"新竹新埔是客家庄，客家人很早就利用秋冬的九降風曬柿餅，一代一代傳下來，現在變成當地有名的產業。"}'::jsonb, '國小社會（康軒版）家鄉與臺灣的觀光；各國家公園管理處公開資料', 'draft'),
  ('post-local-3', 'post-local', 'mc', 3, '{"q":"傳統產業的人越來越少，下面哪一個方法比較能讓它傳下去？","opts":["辦體驗活動，讓更多人認識、買在地產品","不管它，讓它慢慢消失","全部換成跟別的地方一樣的東西"],"a":0,"why":"傳統產業要傳下去，需要有人認識、有人買。辦體驗活動，結合觀光，讓更多人來認識、買在地產品，產業才有收入、才有人願意接著做。"}'::jsonb, '國小社會（康軒版）家鄉與臺灣的觀光；各國家公園管理處公開資料', 'draft'),
  ('sky-neighbors-3', 'sky-neighbors', 'cat', 1, '{"q":"臺灣四周的海，各在哪一邊？","cats":["東邊","西邊","南邊","北邊"],"cards":[{"t":"太平洋","c":0},{"t":"臺灣海峽","c":1},{"t":"巴士海峽","c":2},{"t":"東海","c":3}],"why":"臺灣東邊是太平洋，西邊隔著臺灣海峽和中國大陸相望，南邊隔著巴士海峽和菲律賓相望，北邊是東海。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣與世界', 'draft'),
  ('sky-neighbors-4', 'sky-neighbors', 'tf', 2, '{"q":"從基隆港坐船往北開，會進入東海，再往前可以到日本。","a":true,"why":"臺灣北邊的海是東海，從基隆往北航行經過東海，就能到日本、韓國。南邊的巴士海峽則是往菲律賓的方向。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣與世界', 'draft'),
  ('sky-neighbors-5', 'sky-neighbors', 'who', 2, '{"q":"看著世界地圖，誰說的臺灣位置是對的？","says":[{"n":"小樂","t":"臺灣在日本的西南方"},{"n":"阿邦","t":"臺灣在菲律賓的南方"},{"n":"小晴","t":"臺灣在太平洋的東邊"}],"a":0,"why":"臺灣在日本的西南方、菲律賓的北方；臺灣東邊面對太平洋，所以臺灣在太平洋的西側，不是東邊。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣與世界', 'draft'),
  ('sky-hub-3', 'sky-hub', 'mc', 2, '{"q":"東北亞的國家（像日本、韓國）要去東南亞，飛機常常經過臺灣上空，主要是因為什麼？","opts":["臺灣剛好在兩地中間","臺灣的面積非常大","臺灣的機場最便宜"],"a":0,"why":"臺灣位在東北亞和東南亞的中間，航線常常經過臺灣附近，所以被稱為中點站；和面積大小、機場價錢沒有關係。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣與世界', 'draft'),
  ('sky-hub-4', 'sky-hub', 'mc', 3, '{"q":"東亞的國家要坐船進出哪一片大洋時，臺灣附近的海是重要的通道？","opts":["太平洋","大西洋","北極海"],"a":0,"why":"臺灣東邊就是太平洋，東亞國家的船要進出太平洋常常經過臺灣附近；大西洋在歐洲和美洲之間，離臺灣很遠。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣與世界', 'draft'),
  ('sky-world-4', 'sky-world', 'cloze', 2, '{"q":"世界的陸地和海洋。","text":"世界的陸地主要分成{0}大洲，海洋主要有{1}大洋。","blanks":[{"opts":["五","七","三"],"a":0},{"opts":["三","五","四"],"a":0}],"why":"課本把世界分成五大洲（亞洲、歐洲、非洲、美洲、大洋洲）和三大洋（太平洋、大西洋、印度洋）。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣與世界', 'draft'),
  ('sky-fee-1', 'sky-fee', 'tf', 1, '{"q":"外國飛機只是從臺灣上空飛過、沒有降落，也要付費用給臺灣。","a":true,"why":"飛機經過臺灣管理的「臺北飛航情報區」，臺灣要負責導航和安全，所以飛過不降落也要付「過境航路服務費」。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣與世界', 'draft'),
  ('sky-fee-2', 'sky-fee', 'mc', 2, '{"q":"外國飛機飛過臺灣上空時付的「過境航路服務費」，是為了什麼服務？","opts":["幫飛機導航、維護飛行安全","讓旅客下飛機逛街","幫飛機加油和洗飛機"],"a":0,"why":"飛機沒有降落，用不到機場的加油或觀光；臺灣提供的是空中導航和飛行安全的管理，所以收過境航路服務費。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣與世界', 'draft'),
  ('sky-fee-3', 'sky-fee', 'who', 2, '{"q":"為什麼很多外國飛機付過境費給臺灣？誰說得對？","says":[{"n":"小凱","t":"臺灣在東北亞和東南亞中間，很多航線要經過"},{"n":"小芬","t":"因為臺灣規定外國飛機都要停下來"},{"n":"阿宏","t":"因為那些飛機都是臺灣的"}],"a":0,"why":"臺灣位在東北亞和東南亞航線的中間，很多外國飛機會經過臺灣上空，所以會付過境費；這些飛機不是臺灣的，也不用停下來。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣與世界', 'draft'),
  ('sky-fee-4', 'sky-fee', 'multi', 3, '{"q":"從臺灣的位置可以看出哪些事？（選兩個）","opts":["很多國際航線經過臺灣上空","臺灣可以收到過境航路服務費","臺灣在亞洲的最西邊","飛機都不能飛過臺灣"],"a":[0,1],"why":"臺灣在東北亞和東南亞的中間，國際航線常經過，所以能收過境費。臺灣在亞洲東南邊，不是最西邊；飛機付費就可以飛過。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣與世界', 'draft'),
  ('isles-pacific-4', 'isles-pacific', 'mc', 2, '{"q":"假日想去龜山島玩，要怎麼去？","opts":["從宜蘭搭船過去","從宜蘭搭高鐵過去","從宜蘭走路過去"],"a":0,"why":"龜山島在宜蘭外海的太平洋上，四周都是海，高鐵和走路都到不了，要在宜蘭的港口搭船才能登島。"}'::jsonb, '國小社會五年級上學期（康軒版）〈臺灣我的家〉臺灣的離島', 'draft'),
  ('town-religion-3', 'town-religion', 'cat', 1, '{"q":"這些事情屬於哪一種規範？","cats":["宗教信仰","風俗習慣"],"cards":[{"t":"齋戒月白天不吃東西","c":0},{"t":"星期日到教堂做禮拜","c":0},{"t":"除夕和家人圍爐吃年夜飯","c":1},{"t":"清明節回老家掃墓","c":1}],"why":"齋戒月是伊斯蘭教的規定、做禮拜是基督教的規矩，屬於宗教信仰；年夜飯、掃墓是從以前傳下來的節日習慣，屬於風俗習慣。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('town-religion-4', 'town-religion', 'tf', 2, '{"q":"媽媽常說「舉頭三尺有神明」，提醒大家不要做壞事，這是宗教信仰影響人的行為。","a":true,"why":"相信有神明在看、做壞事會有報應，因此約束自己的行為，這就是宗教信仰的影響，不是法律的處罰。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('town-custom-4', 'town-custom', 'who', 2, '{"q":"清明節帶家人回老家掃墓、祭拜祖先，屬於哪一種規範？誰說得對？","says":[{"n":"小雅","t":"風俗習慣，從以前一代一代傳下來"},{"n":"阿德","t":"法律，不去會被罰錢"},{"n":"小翔","t":"倫理道德，是為了幫助陌生人"}],"a":0,"why":"清明掃墓是傳統節日的習慣，一代一代傳下來，屬於風俗習慣；不去不會被罰，所以不是法律。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('town-moral-4', 'town-moral', 'cat', 1, '{"q":"分分看：這是倫理道德，還是法律？","cats":["倫理道德","法律"],"cards":[{"t":"看到地上有垃圾主動撿起來","c":0},{"t":"孝順父母、友愛同學","c":0},{"t":"騎機車要戴安全帽","c":1},{"t":"行人要走斑馬線","c":1}],"why":"撿垃圾、孝順是心裡覺得應該做的事，屬於倫理道德；戴安全帽、走斑馬線是國家規定，違反可能被罰，屬於法律。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('town-kids-4', 'town-kids', 'cat', 1, '{"q":"依照《兒童及少年福利與權益保障法》，這些人是兒童還是少年？","cats":["兒童（未滿 12 歲）","少年（12 歲以上未滿 18 歲）"],"cards":[{"t":"10 歲的小明","c":0},{"t":"13 歲的小杰","c":1},{"t":"6 歲的妹妹","c":0},{"t":"17 歲的哥哥","c":1}],"why":"法律說的兒童是未滿 12 歲，少年是 12 歲以上、未滿 18 歲，所以 13 歲和 17 歲是少年，6 歲和 10 歲是兒童。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-kids-5', 'town-kids', 'multi', 2, '{"q":"《兒童及少年福利與權益保障法》有哪些保護和照顧？（選三個）","opts":["不能賣酒給未滿 18 歲的人","影片、遊戲要分級","經濟困難的家庭可以得到生活扶助","送每個學生一支手機"],"a":[0,1,2],"why":"這部法律禁止提供菸酒給兒少、要求影片遊戲分級，也照顧經濟困難的家庭；送手機不是這部法律規定的福利。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-kids-6', 'town-kids', 'cat', 2, '{"q":"影片分級：這些情況各是哪一級？","cats":["普遍級","保護級","輔 15 級","限制級"],"cards":[{"t":"所有年齡都可以看","c":0},{"t":"6 歲以上未滿 12 歲要大人陪著看","c":1},{"t":"未滿 15 歲不能看","c":2},{"t":"未滿 18 歲不能看","c":3}],"why":"分級有普遍級（大家都能看）、保護級（6～12 歲要大人陪同輔導）、輔 12、輔 15（未滿 15 歲不能看）、限制級（未滿 18 歲不能看）。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-kids-7', 'town-kids', 'tf', 3, '{"q":"影片分級的主要目的，是讓小朋友少看電視、保護眼睛。","a":false,"why":"分級是為了讓兒童和少年避開不適合年紀的內容，例如暴力、恐怖的畫面；少看電視保護眼睛是另一回事。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-work-3', 'town-work', 'tf', 1, '{"q":"老闆可以僱用 13 歲的國中生每天放學後打工到晚上。","a":false,"why":"《勞動基準法》規定未滿 15 歲原則上不能被僱用，老闆這樣做會被處罰；這是為了讓孩子好好讀書、健康長大。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-work-4', 'town-work', 'mc', 2, '{"q":"法律規定未滿 15 歲原則上不能被僱用工作，主要是為了什麼？","opts":["保護孩子能好好讀書、健康長大","讓老闆可以少付薪水","讓大人有更多工作機會"],"a":0,"why":"這條規定是保護兒少的身心發展，不是為了老闆或大人；未滿 15 歲應該以學習和成長為主。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-fraud-4', 'town-fraud', 'cat', 2, '{"q":"這些是哪一種網路詐騙？","cats":["消費詐騙","網路交友詐騙","打工詐騙"],"cards":[{"t":"超便宜的演唱會門票，要先匯款","c":0},{"t":"網友一直要你傳私人照片","c":1},{"t":"「輕鬆在家賺大錢，不用經驗」","c":2}],"why":"用便宜商品騙人先匯款是消費詐騙；騙取個人照片和資料是交友詐騙；用輕鬆高薪吸引人是打工詐騙。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-fraud-5', 'town-fraud', 'order', 3, '{"q":"網路上遇到可疑的訊息，照防詐「3C」的順序排好。","steps":["冷靜下來，不要急著回覆或匯款","查證對方說的是真是假","打 165 反詐騙專線問清楚"],"why":"3C 是 Calm 冷靜、Check 查證、Call 打 165。先冷靜才不會被催著做決定，再查證，最後打 165 請專人確認。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-fraud-6', 'town-fraud', 'who', 2, '{"q":"網友說可以幫你賺很多錢，但不准告訴爸媽。誰的判斷最好？","says":[{"n":"小宜","t":"要保密又說很好賺，很可能是詐騙，要告訴大人"},{"n":"阿翔","t":"網友人很好，照他說的做"},{"n":"小琪","t":"先匯一點錢試試看"}],"a":0,"why":"一直催促、要求保密、逼你做不願意的事，是詐騙三大特徵；這時要告訴大人、打 165 查證，不要匯錢。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('town-copy-3', 'town-copy', 'tf', 1, '{"q":"網路上的文章只要把作者的名字刪掉，就可以當成自己的作品使用。","a":false,"why":"刪掉作者名字等於把別人的作品說成自己的，會侵害著作權；引用別人的作品要寫清楚作者和出處。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('vil-ama-1', 'vil-ama', 'mc', 1, '{"q":"臺灣的「海女」是在做什麼工作？","opts":["女性潛到海裡採集海產","男性划船到遠洋捕魚","女性在漁港賣魚和開店"],"a":0,"why":"海女是潛水採集石花菜、海膽、螺類等海產的女性，主要在東北角和澎湖；遠洋捕魚多是男性漁民，賣魚也不叫海女。"}'::jsonb, '國小社會五年級上學期（康軒版）第一單元〈臺灣是我的家鄉〉', 'draft'),
  ('vil-ama-2', 'vil-ama', 'tf', 2, '{"q":"海女下海採集回來後，就不需要再做其他事情了。","a":false,"why":"海女除了下海採集，回家還要幫忙家務、照顧家人，工作很辛苦，所以「只要採集就好」的說法不對。"}'::jsonb, '國小社會五年級上學期（康軒版）第一單元〈臺灣是我的家鄉〉', 'draft'),
  ('vil-ama-3', 'vil-ama', 'multi', 2, '{"q":"關於海女，哪些說法是對的？（選兩個）","opts":["工作辛苦又危險","現在做的人越來越少","待遇很好，年輕人搶著做","都在高山上工作"],"a":[0,1],"why":"海女要潛水、受天氣和海浪影響，辛苦又危險，現在從事的人越來越少、年紀也偏大；她們在海邊工作，不是高山。"}'::jsonb, '國小社會五年級上學期（康軒版）第一單元〈臺灣是我的家鄉〉', 'draft'),
  ('vil-ama-4', 'vil-ama', 'who', 3, '{"q":"想更了解海女的工作，誰的方法最好？","says":[{"n":"甜甜","t":"參加地方的導覽，實際走訪潮間帶"},{"n":"阿哲","t":"到超市看海鮮的價錢"},{"n":"小莉","t":"上網看美人魚的故事"}],"a":0,"why":"實地走訪、聽在地導覽，最能了解海女怎麼工作；超市只看得到海鮮，美人魚是童話，和海女無關。"}'::jsonb, '國小社會五年級上學期（康軒版）第一單元〈臺灣是我的家鄉〉', 'draft'),
  ('vil-net-1', 'vil-net', 'tf', 1, '{"q":"牽罟是很多人一起合作，把漁網從海裡拉上岸的捕魚方式。","a":true,"why":"牽罟要先把大網撒到海裡，再由岸上很多人一起拉網上岸，靠的是大家合作，所以全村都會一起參加。"}'::jsonb, '國小社會五年級上學期（康軒版）第一單元〈臺灣是我的家鄉〉', 'draft'),
  ('vil-net-2', 'vil-net', 'tf', 2, '{"q":"現在參加牽罟體驗活動，一定要是專業的漁夫才可以。","a":false,"why":"現在很多海邊有牽罟體驗，一般民眾、學生都可以一起拉網，認識傳統的捕魚方式，不必是專業漁夫。"}'::jsonb, '國小社會五年級上學期（康軒版）第一單元〈臺灣是我的家鄉〉', 'draft'),
  ('vil-net-3', 'vil-net', 'mc', 2, '{"q":"牽罟這種捕魚方式，最需要什麼？","opts":["很多人一起合作","一艘很大的遠洋漁船","一個人很會游泳"],"a":0,"why":"牽罟的漁網又大又重，要很多人一起在岸上拉才拉得動，所以最需要合作；不需要遠洋漁船，也不是一個人就能完成。"}'::jsonb, '國小社會五年級上學期（康軒版）第一單元〈臺灣是我的家鄉〉', 'draft'),
  ('vil-net-4', 'vil-net', 'who', 3, '{"q":"為什麼臺灣有很多和海有關的活動，像牽罟、海女、迎媽祖？誰說得最好？","says":[{"n":"小安","t":"臺灣四面環海，人們的生活和海洋關係很深"},{"n":"阿成","t":"因為臺灣沒有山"},{"n":"小芸","t":"因為法律規定一定要辦"}],"a":0,"why":"臺灣四面環海，很多人靠海生活，所以發展出和海洋有關的工作、信仰和節慶；臺灣其實山很多，這些活動也不是法律規定的。"}'::jsonb, '國小社會五年級上學期（康軒版）第一單元〈臺灣是我的家鄉〉', 'draft'),
  ('vil-faith-1', 'vil-faith', 'cat', 1, '{"q":"這些信仰和節慶，主要屬於哪一個族群的文化？","cats":["漢人","原住民族"],"cards":[{"t":"迎媽祖","c":0},{"t":"蓋廟宇祭拜神明","c":0},{"t":"拼板舟下水前舉行祭典","c":1},{"t":"信仰祖靈和自然神靈","c":1}],"why":"媽祖和廟宇的神明信仰主要是漢人文化；達悟族的拼板舟下水祭、原住民族信仰祖靈和山海等自然神靈，屬於原住民族文化。"}'::jsonb, '國小社會五年級上學期（康軒版）第一單元〈臺灣是我的家鄉〉', 'draft'),
  ('vil-faith-2', 'vil-faith', 'mc', 2, '{"q":"漁民出海前常到廟裡拜拜，祈求出海平安。他們最常拜的是哪一位神明？","opts":["媽祖","土地公","文昌帝君"],"a":0,"why":"媽祖被認為是保佑海上平安的神明，漁村大多有媽祖廟；土地公保佑土地和農作，文昌帝君保佑讀書考試。"}'::jsonb, '國小社會五年級上學期（康軒版）第一單元〈臺灣是我的家鄉〉', 'draft'),
  ('vil-faith-3', 'vil-faith', 'tf', 2, '{"q":"蘭嶼達悟族的新拼板舟下水時，全村會一起舉行下水祭。","a":true,"why":"拼板舟是達悟族用許多木板拼成的船，新船下水時會舉行祭典，祈求出海平安，是原住民族的海洋文化。"}'::jsonb, '國小社會五年級上學期（康軒版）第一單元〈臺灣是我的家鄉〉', 'draft'),
  ('vil-faith-4', 'vil-faith', 'who', 3, '{"q":"關於臺灣的海洋信仰，誰說得對？","says":[{"n":"小美","t":"漢人有媽祖信仰，原住民族也有和海洋有關的祭典"},{"n":"阿傑","t":"只有漢人和海洋有關係"},{"n":"小凡","t":"原住民族都不信仰神靈"}],"a":0,"why":"漢人漁村有媽祖信仰，原住民族也有海祭、拼板舟下水祭，並信仰祖靈和自然神靈，所以兩個族群都有海洋文化。"}'::jsonb, '國小社會五年級上學期（康軒版）第一單元〈臺灣是我的家鄉〉', 'draft'),
  ('home-land-1', 'home-land', 'multi', 1, '{"q":"下面哪些島嶼屬於我國的範圍？（選三個）","opts":["臺灣島","金門列嶼","綠島","沖繩島"],"a":[0,1,2],"why":"我國的範圍包括臺灣、澎湖、金門、馬祖，以及綠島、蘭嶼、龜山島等島嶼；沖繩島屬於日本，不是我國的範圍。"}'::jsonb, '國小社會五年級上學期（康軒版）第一單元〈臺灣是我的家鄉〉', 'draft'),
  ('home-land-2', 'home-land', 'mc', 2, '{"q":"我國國土的總面積大約是多少？","opts":["約 3 萬 6 千平方公里","約 360 平方公里","約 360 萬平方公里"],"a":0,"why":"我國國土（臺灣、澎湖、金門、馬祖等）總面積約 3 萬 6 千平方公里；360 平方公里只像一個小鄉鎮，360 萬平方公里比印度還大。"}'::jsonb, '國小社會五年級上學期（康軒版）第一單元〈臺灣是我的家鄉〉', 'draft'),
  ('home-land-3', 'home-land', 'tf', 2, '{"q":"我國的國土只有臺灣本島一座島。","a":false,"why":"除了臺灣本島，還有澎湖群島、金門、馬祖，以及綠島、蘭嶼、龜山島、小琉球等很多島嶼，都是我國的範圍。"}'::jsonb, '國小社會五年級上學期（康軒版）第一單元〈臺灣是我的家鄉〉', 'draft'),
  ('home-land-4', 'home-land', 'cloze', 3, '{"q":"暑假的島嶼之旅。","text":"小白從臺灣島搭船，到了位在{0}的琉球嶼，琉球嶼在臺灣島的{1}方。","blanks":[{"opts":["臺灣海峽","太平洋","南海"],"a":0},{"opts":["西南","東北","東南"],"a":0}],"why":"琉球嶼（小琉球）在屏東東港外海，位在臺灣海峽，在臺灣島的西南方；反過來說，臺灣島在琉球嶼的東北方。"}'::jsonb, '國小社會五年級上學期（康軒版）第一單元〈臺灣是我的家鄉〉', 'draft'),
  ('home-newcomer-1', 'home-newcomer', 'mc', 1, '{"q":"政府訂每年哪一天為「移民節」？","opts":["12 月 18 日","1 月 18 日","7 月 18 日"],"a":0,"why":"政府把每年 12 月 18 日訂為移民節，這天也是聯合國的國際移民日，提醒大家關心新住民、尊重多元文化。"}'::jsonb, '國小社會五年級上學期（康軒版）第一單元〈臺灣是我的家鄉〉', 'draft'),
  ('home-newcomer-2', 'home-newcomer', 'tf', 1, '{"q":"近年移居臺灣的外籍新住民，有很多來自越南、印尼等東南亞國家。","a":true,"why":"外籍新住民裡，來自越南、印尼、泰國、菲律賓等東南亞國家的人很多，他們也把家鄉的語言、飲食和文化帶來臺灣。"}'::jsonb, '國小社會五年級上學期（康軒版）第一單元〈臺灣是我的家鄉〉', 'draft'),
  ('home-newcomer-3', 'home-newcomer', 'who', 2, '{"q":"移民節的活動該怎麼辦？誰的想法符合移民節的精神？","says":[{"n":"小欣","t":"辦美食和文化表演，讓大家認識不同的文化"},{"n":"阿明","t":"要求新住民完全放棄原本的文化"},{"n":"小強","t":"只讓新住民自己參加就好"}],"a":0,"why":"移民節是要尊重多元文化、關心新住民，所以要讓大家互相認識；要求放棄原本文化或把新住民隔開，都違反這個精神。"}'::jsonb, '國小社會五年級上學期（康軒版）第一單元〈臺灣是我的家鄉〉', 'draft'),
  ('home-newcomer-4', 'home-newcomer', 'multi', 3, '{"q":"哪些做法能讓新住民更好適應臺灣的生活？（選兩個）","opts":["提供交流和學習中文的機會","鼓勵大家認識不同的文化","嘲笑他們說話的口音","規定他們只能說中文"],"a":[0,1],"why":"提供交流、學習的機會，並鼓勵大家認識彼此的文化，能幫助新住民適應；嘲笑口音或禁止說母語，都是不尊重。"}'::jsonb, '國小社會五年級上學期（康軒版）第一單元〈臺灣是我的家鄉〉', 'draft'),
  ('home-rites-1', 'home-rites', 'multi', 1, '{"q":"生命禮俗是在人生哪些重要階段舉行的？（選三個）","opts":["出生","結婚","過世","每天上學"],"a":[0,1,2],"why":"生命禮俗涵蓋出生、成年、結婚、死亡等人生重要階段；每天上學是日常生活，不是人生階段的禮俗。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('home-rites-2', 'home-rites', 'mc', 2, '{"q":"阿姨家生了寶寶，滿月時送紅蛋和油飯給親友，這是在慶祝人生哪一個階段？","opts":["出生","成年","結婚"],"a":0,"why":"寶寶出生滿一個月時送油飯、紅蛋，叫做彌月，是祝福孩子剛出生能平安長大的生命禮俗，屬於出生階段。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('home-rites-3', 'home-rites', 'cat', 2, '{"q":"這些生命禮俗屬於人生哪一個階段？","cats":["出生","成年","結婚","死亡"],"cards":[{"t":"彌月送油飯","c":0},{"t":"臺南做十六歲","c":1},{"t":"迎娶、拜別父母","c":2},{"t":"舉行告別式","c":3}],"why":"彌月慶祝出生；臺南的做十六歲是傳統成年禮；迎娶、拜別父母是結婚的儀式；告別式是送別過世的親人。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('home-rites-4', 'home-rites', 'mc', 3, '{"q":"小君參加阿姨的婚禮，看到很多傳統儀式。婚禮屬於哪一類活動？","opts":["生命禮俗","宗教規範","法律規定"],"a":0,"why":"結婚是人生的重要階段，婚禮的傳統儀式屬於生命禮俗；它不是某個宗教的規定，也不是違反就會被罰的法律。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('home-change-1', 'home-change', 'tf', 1, '{"q":"社會規範一旦形成，就永遠不應該改變。","a":false,"why":"規範會隨著時代調整。例如以前只有生男孩才送油飯，現在生女孩也一樣慶祝；不合時宜的規範可以適度改變。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('home-change-2', 'home-change', 'who', 2, '{"q":"阿嬤說：「只有生男孩才要送油飯，女孩不用。」誰的回應符合現代社會的觀念？","says":[{"n":"小雯","t":"現在男孩女孩一樣重要，都可以送油飯慶祝"},{"n":"阿德","t":"傳統一定不能改，阿嬤說得對"},{"n":"小傑","t":"送油飯是法律規定，不送會被罰"}],"a":0,"why":"規範會隨時代改變，現代社會重視男女平等，所以男孩女孩出生都可以慶祝；送油飯是習俗，不是法律。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('home-change-3', 'home-change', 'tf', 2, '{"q":"農曆七月是鬼月，所以政府規定這個月不能結婚。","a":false,"why":"鬼月不結婚是部分人的習俗，政府沒有這樣的法律規定；想不想在鬼月結婚，是每個家庭自己的選擇。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('home-change-4', 'home-change', 'mc', 3, '{"q":"大家一起遵守社會規範，最主要的好處是什麼？","opts":["和諧相處、減少衝突","讓自己比別人更方便","讓少數人得到特權"],"a":0,"why":"遵守規範能讓大家互相尊重、維持秩序、減少紛爭；它不是讓自己方便，也不是讓少數人得到特權。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律', 'draft'),
  ('home-rule-1', 'home-rule', 'tf', 1, '{"q":"在法治社會中，不只人民要守法，政府做事也要依照法律。","a":true,"why":"法治的意思是大家都在法律底下，政府也要依法行事；這樣政府不能隨便亂用權力，才能保障人民、實現公平。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('home-rule-2', 'home-rule', 'mc', 2, '{"q":"法律是由誰制定的？","opts":["政府（立法機關）","每個家庭自己","各地的廟宇"],"a":0,"why":"法律由國家的立法機關制定、政府執行；家庭的規矩和廟裡的規定都不是法律，沒有國家的強制力。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('home-rule-3', 'home-rule', 'multi', 2, '{"q":"制定法律的目的有哪些？（選三個）","opts":["保護人民的權利","維持社會秩序","規範人民與政府的行為","讓政府可以不守規則"],"a":[0,1,2],"why":"法律保護人民的權利、維持社會秩序，也規範人民和政府的行為；政府也要守法，所以「政府可以不守規則」是錯的。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('home-rule-4', 'home-rule', 'who', 3, '{"q":"關於法律，誰說得對？","says":[{"n":"小凱","t":"法律也管政府，政府要依法行事"},{"n":"阿美","t":"法律只是用來處罰人民的"},{"n":"小華","t":"只有法官才需要守法"}],"a":0,"why":"法律規範所有人，包括政府和每一位人民；法律不只處罰，也保障權利，並不是只有法官要守法。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('home-group-1', 'home-group', 'tf', 1, '{"q":"政府制定《國家語言發展法》，是為了保障各族群使用母語的權利。","a":true,"why":"《國家語言發展法》保障臺灣各族群的語言，例如客語、原住民族語、臺灣手語，讓大家都能學習和使用自己的母語。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('home-group-2', 'home-group', 'mc', 2, '{"q":"學校開始推動臺灣手語課程，增進學生和聾人的溝通，是哪一部法律促成的？","opts":["國家語言發展法","著作權法","勞動基準法"],"a":0,"why":"臺灣手語是《國家語言發展法》保障的國家語言之一；著作權法保護作品，勞動基準法管工作，都和手語無關。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('home-group-3', 'home-group', 'mc', 2, '{"q":"政府設立「客語友善環境」的標示，主要目的是什麼？","opts":["保障說客語的權利","推廣觀光賺錢","鼓勵大家只說英文"],"a":0,"why":"客語友善環境讓說客語的人在店家、機關都能用客語溝通，是保障客家族群使用母語的權利，不是為了觀光或推英文。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('home-group-4', 'home-group', 'who', 3, '{"q":"為什麼有些法律是專門為某一群人制定的？誰說得對？","says":[{"n":"小澄","t":"為了保護特定群體的文化和權益"},{"n":"阿忠","t":"為了讓少數人得到特權"},{"n":"小芳","t":"有了一般法律就不需要"}],"a":0,"why":"有些群體的文化或權益容易被忽略，例如語言少有人說的族群，專屬法律是為了保護他們，讓大家更公平，不是特權。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('home-rumor-1', 'home-rumor', 'tf', 1, '{"q":"在網路上散布關於同學的不實謠言，可能要負法律責任。","a":true,"why":"網路不是法外之地，散布不實言論傷害別人的名譽，可能違反法律，要負起責任；網路上的行為和現實生活一樣要守法。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('home-rumor-2', 'home-rumor', 'mc', 2, '{"q":"阿海在網路上散布關於同學的假消息，可能會有什麼後果？","opts":["需要負法律責任","得到大家的稱讚","可以領到獎金"],"a":0,"why":"散布不實消息會傷害別人，可能要負法律責任；這種行為不會被稱讚，也沒有獎金。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('home-rumor-3', 'home-rumor', 'tf', 2, '{"q":"網路是虛擬世界，在網路上說的話不受法律規範。","a":false,"why":"網路上的言論和行為一樣受到法律規範，散布謠言、侵害著作權、詐騙，在網路上做也會被處罰。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('home-rumor-4', 'home-rumor', 'who', 3, '{"q":"看到群組裡有人轉傳一則沒有證據的消息，說某位同學偷東西。誰的做法最好？","says":[{"n":"小慧","t":"不轉傳，先查證，也提醒大家不要亂傳"},{"n":"阿傑","t":"馬上轉傳給更多人知道"},{"n":"小平","t":"加上自己猜的內容再轉傳"}],"a":0,"why":"沒查證就轉傳可能散布不實言論、傷害同學，也可能要負法律責任；先查證、不轉傳才是對的做法。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('home-redress-1', 'home-redress', 'mc', 1, '{"q":"小志在公園玩時，因為溜滑梯壞掉而受傷，後續怎麼做比較適當？","opts":["向政府請求賠償","只能自認倒楣","大哭大鬧罵管理人員"],"a":0,"why":"公園是政府管理的公共設施，設施壞掉害人受傷，可以依《國家賠償法》向政府請求賠償；自認倒楣或吵鬧都不能解決問題。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('home-redress-2', 'home-redress', 'tf', 2, '{"q":"公共設施沒有管理好讓人受傷，人民可以依法向政府請求賠償。","a":true,"why":"這叫國家賠償。政府也要依法負責，公共設施（像公園、道路）管理不好造成人民受傷或損失，人民可以請求賠償。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('home-redress-3', 'home-redress', 'who', 2, '{"q":"人行道的坑洞讓阿公跌倒受傷。誰說得對？","says":[{"n":"小如","t":"可以依法向政府請求賠償"},{"n":"阿翔","t":"政府不用守法，不能賠"},{"n":"小晴","t":"只能怪阿公自己走路不小心"}],"a":0,"why":"人行道是政府管理的公共設施，沒修好害人受傷，可以請求國家賠償；政府也要守法、負責，不能說政府不用守法。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('home-redress-4', 'home-redress', 'mc', 3, '{"q":"人民可以向政府請求「國家賠償」，最能說明哪一個觀念？","opts":["政府也要依法負起責任","政府永遠不會出錯","人民不需要守法"],"a":0,"why":"國家賠償說明政府做錯事也要負責，這是法治的精神；政府也可能出錯，而人民一樣要守法。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('home-crime-1', 'home-crime', 'mc', 1, '{"q":"下列哪一種行為，最可能被判刑坐牢？","opts":["偷竊別人的財物","在電影院講話太大聲","排隊時聊天"],"a":0,"why":"偷竊違反《刑法》，可能被判刑坐牢；在電影院太大聲、排隊聊天是道德或禮貌的問題，不會被判刑。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('home-crime-2', 'home-crime', 'cat', 2, '{"q":"這些規定，哪些是法律？","cats":["法律","不是法律"],"cards":[{"t":"行人要走行人穿越道","c":0},{"t":"汽車不能違規停車","c":0},{"t":"騎機車要戴安全帽","c":0},{"t":"過年時長輩發壓歲錢","c":1}],"why":"走斑馬線、不違規停車、戴安全帽都是交通法規，違反會被罰；發壓歲錢是過年的風俗習慣，不是法律。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('home-crime-3', 'home-crime', 'tf', 2, '{"q":"小李為了快一點，沒走斑馬線直接穿越馬路，這是違法的行為。","a":true,"why":"交通法規規定行人要走行人穿越道，任意穿越馬路違法，可能被罰款，也很危險；這不只是道德問題。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('home-crime-4', 'home-crime', 'who', 3, '{"q":"小澄過馬路時闖紅燈，會有什麼後果？誰說得對？","says":[{"n":"阿華","t":"違反交通法規可能被罰，也危及自己的安全"},{"n":"小美","t":"只會被別人罵，沒有其他後果"},{"n":"小志","t":"只是違反風俗習慣而已"}],"a":0,"why":"闖紅燈違反交通法規，可能被開罰單，還可能被車撞；它有法律的強制力，不只是被罵或違反風俗。"}'::jsonb, '國小社會五年級上學期（康軒版）社會規範與法律；全國法規資料庫', 'draft'),
  ('home-inquiry-1', 'home-inquiry', 'mc', 1, '{"q":"想整理大家對一件事的「贊成」和「反對」理由，用哪一種方法最清楚？","opts":["T 表","地圖","時間軸"],"a":0,"why":"T 表把紙分成左右兩邊，一邊寫贊成、一邊寫反對，很容易比較；地圖看位置，時間軸看先後順序。"}'::jsonb, '國小社會五年級上學期（康軒版）第一單元〈臺灣是我的家鄉〉', 'draft'),
  ('home-inquiry-2', 'home-inquiry', 'order', 2, '{"q":"小樂想探究「電視節目為什麼要分級」，把步驟排好。","steps":["提出問題：為什麼要分級？","蒐集資料：訪問家人、找新聞","整理分析：用 T 表整理贊成和反對","行動省思：想想還有什麼也該分級"],"why":"探究的步驟是先提出問題，再蒐集資料，接著整理分析，最後行動與省思；沒有資料就無法整理，所以順序不能顛倒。"}'::jsonb, '國小社會五年級上學期（康軒版）第一單元〈臺灣是我的家鄉〉', 'draft'),
  ('home-inquiry-3', 'home-inquiry', 'mc', 2, '{"q":"想查有關法律的正確知識，去哪裡蒐集資料最適當？","opts":["圖書館","遊樂場","百貨公司"],"a":0,"why":"圖書館有法律相關的書和資料，也能查政府網站；遊樂場和百貨公司不是找資料的地方。"}'::jsonb, '國小社會五年級上學期（康軒版）第一單元〈臺灣是我的家鄉〉', 'draft'),
  ('home-inquiry-4', 'home-inquiry', 'multi', 3, '{"q":"做探究報告時，可以蒐集哪些資料？（選三個）","opts":["新聞報導","訪問別人的看法","法律的內容","自己隨便猜的答案"],"a":[0,1,2],"why":"新聞、訪談、法律條文都是有根據的資料；自己猜的答案沒有根據，不能當作探究的資料。"}'::jsonb, '國小社會五年級上學期（康軒版）第一單元〈臺灣是我的家鄉〉', 'draft'),
  ('geo-plate-1', 'geo-plate', 'mc', 1, '{"q":"臺灣島是怎麼形成的？","opts":["兩個板塊互相推擠，地面慢慢隆起","火山一次噴發堆出來的","海水退掉以後才露出來"],"a":0,"why":"臺灣位在歐亞板塊和菲律賓海板塊的交界，兩個板塊長期互相推擠，地面慢慢隆起成島；不是單一火山噴發，也不是海水退去造成的。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-plate-2', 'geo-plate', 'tf', 1, '{"q":"臺灣位在兩個板塊交界的地方，所以常常發生地震。","a":true,"why":"板塊交界處岩層一直受到擠壓，累積的力量釋放出來就是地震，所以臺灣地震頻繁，例如 1999 年的九二一大地震。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-plate-3', 'geo-plate', 'cloze', 2, '{"q":"臺灣島的形成。","text":"臺灣位在{0}板塊和{1}板塊的交界處，長期推擠而隆起。","blanks":[{"opts":["歐亞","非洲","南極"],"a":0},{"opts":["菲律賓海","印度洋","北美"],"a":0}],"why":"臺灣在歐亞板塊和菲律賓海板塊之間，兩個板塊互相擠壓讓臺灣島隆起，也讓臺灣多地震。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-plate-4', 'geo-plate', 'who', 3, '{"q":"為什麼臺灣的山脈大多是南北走向？誰說得最有道理？","says":[{"n":"小宇","t":"板塊從東西兩邊推擠，擠出南北長的山脈"},{"n":"阿青","t":"因為河流都往南北流"},{"n":"小蓉","t":"因為颱風都從南邊吹來"}],"a":0,"why":"兩個板塊從東西兩側互相推擠，地面被擠成一條條南北向的山脈，所以臺灣南北長、東西窄；和河流、颱風方向無關。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-landform-1', 'geo-landform', 'cat', 1, '{"q":"這些地方屬於哪一種地形？","cats":["盆地","台地","平原"],"cards":[{"t":"臺北（四周被山圍住的低地）","c":0},{"t":"桃園（比四周高、頂部平坦）","c":1},{"t":"嘉南（又大又平、靠近海）","c":2}],"why":"四周高、中間低平的是盆地，如臺北；地勢比四周高但頂部平坦的是台地，如桃園；廣大平坦的低地是平原，如嘉南平原。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-landform-2', 'geo-landform', 'tf', 2, '{"q":"臺灣的平原、盆地、台地多分布在西部，早期多發展農業，後來很多發展成都市。","a":true,"why":"地勢平坦的地方好耕作、好蓋房子、交通方便，所以早期種田，人口和交通越來越多後，像臺北盆地就變成都市。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-landform-3', 'geo-landform', 'mc', 2, '{"q":"臺灣島的外形和山脈有什麼特色？","opts":["南北長、東西窄，山脈多南北走向","東西長、南北窄，山脈多東西走向","圓圓的，山都集中在海邊"],"a":0,"why":"臺灣島南北長約 390 多公里、東西窄，中央山脈等主要山脈都是南北走向，河川則從中間往東西兩邊流。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-landform-4', 'geo-landform', 'multi', 3, '{"q":"下面哪些是「地勢平坦」的地形？（選三個）","opts":["平原","盆地","台地","山地"],"a":[0,1,2],"why":"平原、盆地底部、台地頂部都比較平坦，適合農業和都市；山地高低起伏大，屬於地勢崎嶇的地形。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-pond-1', 'geo-pond', 'mc', 1, '{"q":"早期桃園台地的人挖「埤塘」，主要是為了什麼？","opts":["儲存雨水方便灌溉","養觀賞用的錦鯉","防止颱風吹壞房子"],"a":0,"why":"桃園台地地勢比較高，河水不容易引上來，所以挖埤塘儲存雨水來灌溉農田；不是為了觀賞或防颱。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-pond-2', 'geo-pond', 'tf', 2, '{"q":"桃園的埤塘到現在一個都沒有減少。","a":false,"why":"後來農業變少，很多埤塘被填平，蓋了工廠、住宅、擴建機場，也有一些改建成生態公園，所以埤塘數量變少了。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-pond-3', 'geo-pond', 'who', 2, '{"q":"桃園台地為什麼特別需要埤塘？誰說得對？","says":[{"n":"小方","t":"地勢比較高，河水不容易引上來灌溉"},{"n":"阿瑞","t":"因為桃園天天下大雨"},{"n":"小玲","t":"因為桃園在海的中間"}],"a":0,"why":"台地比四周高，河水引不上去，只好就地挖埤塘把雨水存起來；桃園並不是天天下大雨，也不在海中間。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-pond-4', 'geo-pond', 'multi', 3, '{"q":"桃園的埤塘後來有哪些改變？（選兩個以上）","opts":["被填平蓋工廠或住宅","改建成生態公園","擴建機場用掉土地","全部變成鹽田"],"a":[0,1,2],"why":"農業減少後，埤塘有的被填平蓋工廠、住宅或擴建機場，有的改成生態公園；桃園不是曬鹽的地方，沒有變成鹽田。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-hill-1', 'geo-hill', 'mc', 1, '{"q":"早期丘陵地區常常種什麼？","opts":["果樹和茶樹","稻米和甘蔗","海帶和蚵仔"],"a":0,"why":"丘陵地勢起伏、排水好，適合種果樹和茶樹；稻米甘蔗多種在平原，海帶蚵仔在海邊養殖。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-hill-2', 'geo-hill', 'cat', 2, '{"q":"這些地方後來轉型成什麼？","cats":["科技重鎮","森林遊樂區"],"cards":[{"t":"竹東丘陵（以前種茶）","c":0},{"t":"新竹科學園區一帶","c":0},{"t":"八仙山（以前伐木）","c":1}],"why":"竹東丘陵早期種茶，後來設了大學和新竹科學園區，變成科技重鎮；八仙山早期是伐木聚落，現在轉型成結合保育的森林遊樂區。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-hill-3', 'geo-hill', 'tf', 2, '{"q":"丘陵和山地占臺灣的面積比平原還多。","a":true,"why":"臺灣山多平原少，丘陵和山地加起來占了大部分面積，地勢起伏大，平坦的地方大多在西部。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-hill-4', 'geo-hill', 'who', 3, '{"q":"以前山地大量砍伐樹木，現在改成森林遊樂區，這樣的改變有什麼好處？誰說得最好？","says":[{"n":"小婷","t":"保護山林，也能讓大家來認識自然"},{"n":"阿凱","t":"可以砍更多木頭來賣"},{"n":"小龍","t":"山上就不會再下雨"}],"a":0,"why":"過度伐木會破壞山林，改成森林遊樂區可以保育森林，又能發展觀光、讓人認識自然；不是為了砍更多木頭，也不會影響下雨。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-river-1', 'geo-river', 'multi', 1, '{"q":"臺灣的河川有哪些特色？（選三個）","opts":["長度短","坡度陡","水流急","又寬又慢、很適合大船航行"],"a":[0,1,2],"why":"臺灣河川多從中央山地發源，到海的距離短、高低落差大，所以長度短、坡度陡、水流急，不適合大船航行。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-river-2', 'geo-river', 'mc', 2, '{"q":"臺灣河川坡度陡、水流急，容易造成什麼問題？","opts":["雨水很快流進海裡，容易缺水","河水流得太慢，常常結冰","船可以很快開到山上"],"a":0,"why":"水流急，下的雨很快就流進海裡留不住，所以臺灣雖然雨多，還是容易缺水；臺灣河川不會結冰，船也開不上山。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-river-3', 'geo-river', 'tf', 2, '{"q":"在河川上游蓋水庫，可以蓄水和發電，但也可能破壞生態、淹沒原本的聚落。","a":true,"why":"水庫能存水、發電，解決缺水；但蓋水庫要把山谷淹起來，原本的村落和生態會受影響，例如翡翠水庫淹沒了碧山村。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-river-4', 'geo-river', 'cat', 3, '{"q":"河川的上游和下游，土地常怎麼利用？","cats":["上游","下游"],"cards":[{"t":"蓋水庫蓄水發電","c":0},{"t":"河道寬、遍布農田和工業區","c":1},{"t":"建橋梁和住家","c":1}],"why":"上游在山區、地勢高，適合蓋水庫；下游河道寬、地勢平坦，土地多元利用，有農田、工業區、橋梁和住家。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-coast-1', 'geo-coast', 'cat', 1, '{"q":"臺灣四邊的海岸各是什麼樣子？","cats":["西部","北部","東部","南部"],"cards":[{"t":"沙灘、沙洲","c":0},{"t":"岬角和海灣曲折","c":1},{"t":"斷崖峭壁","c":2},{"t":"珊瑚礁","c":3}],"why":"西部是平直的沙岸，北部岬角海灣曲折，東部山直接臨海形成斷崖，南部（墾丁）有珊瑚礁海岸。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-coast-2', 'geo-coast', 'mc', 2, '{"q":"彰化王功一帶的海岸很適合養蚵，它屬於哪一種海岸？","opts":["西部的沙岸","東部的斷崖","北部的岬灣"],"a":0,"why":"西部海岸平坦、多沙灘和沙洲，潮間帶寬，適合養蚵和養殖漁業；東部斷崖海很深，北部岬灣多做港口。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-coast-3', 'geo-coast', 'mc', 2, '{"q":"北部海岸曲折、有很多海灣，最適合發展什麼？","opts":["港口和漁業","大面積的鹽田","種植稻米"],"a":0,"why":"海灣可以擋風浪，讓船安全停靠，所以北部適合蓋港口、發展漁業和貿易；鹽田要平坦的沙岸，稻米種在平原。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-coast-4', 'geo-coast', 'who', 3, '{"q":"恆春古城的城牆用了什麼材料？誰說得對？","says":[{"n":"小海","t":"南部海岸的珊瑚礁石"},{"n":"阿山","t":"東部斷崖的大理石"},{"n":"小沙","t":"西部海邊的沙子"}],"a":0,"why":"南部有珊瑚礁海岸，早期居民就地取材用珊瑚礁石蓋恆春古城牆；現在珊瑚礁海岸則是浮潛觀光的好地方。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-typhoon-1', 'geo-typhoon', 'mc', 1, '{"q":"颱風大多在什麼季節來臺灣？","opts":["夏天和秋天","冬天和春天","一年四季都一樣多"],"a":0,"why":"颱風集中在夏、秋兩季，帶來強風豪雨；冬天吹東北季風，很少有颱風。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-typhoon-2', 'geo-typhoon', 'tf', 2, '{"q":"颱風只會帶來災害，對臺灣一點好處都沒有。","a":false,"why":"颱風的強風豪雨會造成災害，但帶來的雨水也能替水庫蓄水，是臺灣重要的水源之一。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-typhoon-3', 'geo-typhoon', 'who', 2, '{"q":"颱風要來了，漁村的大家要做什麼？誰的做法最好？","says":[{"n":"阿海伯","t":"漁船回港綁好，門窗加固，準備好避難"},{"n":"阿宏","t":"趁浪大出海捕更多魚"},{"n":"小美","t":"到海邊看大浪拍照"}],"a":0,"why":"颱風帶來強風大浪，漁船要回港、房子要加固，人也要避開危險；出海或到海邊看浪都非常危險。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-typhoon-4', 'geo-typhoon', 'multi', 3, '{"q":"颱風可能帶來哪些影響？（選三個）","opts":["強風吹壞房子和農作物","豪雨造成淹水","雨水替水庫蓄水","讓冬天變得更冷"],"a":[0,1,2],"why":"颱風有強風和豪雨，會吹壞房屋作物、造成淹水，但也替水庫補水；冬天變冷是寒流和東北季風造成的，跟颱風無關。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-flood-1', 'geo-flood', 'mc', 1, '{"q":"每年 5～9 月，臺灣常因為梅雨和颱風的豪雨發生什麼災害？","opts":["水災和土石流","旱災和寒害","下雪和結冰"],"a":0,"why":"5～9 月有梅雨和颱風，雨量大又集中，平地容易淹水，山區容易發生土石流；旱災多在冬春，寒害在冬天。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-flood-2', 'geo-flood', 'tf', 2, '{"q":"2009 年莫拉克颱風帶來豪雨，造成土石流，掩埋了高雄的小林村。","a":true,"why":"莫拉克颱風帶來非常大的雨量，山區土石鬆動形成土石流，小林村被掩埋，是臺灣很嚴重的天然災害。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-flood-3', 'geo-flood', 'cat', 2, '{"q":"這些災害比較常發生在平地還是山區？","cats":["平地","山區"],"cards":[{"t":"淹水","c":0},{"t":"低窪的房子進水","c":0},{"t":"土石流","c":1},{"t":"坡地土石往下衝","c":1}],"why":"平地地勢低，雨水來不及排走就淹水；山區坡陡，大雨讓土石鬆動往下衝，就是土石流。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-flood-4', 'geo-flood', 'who', 3, '{"q":"颱風天山區下了好幾天大雨，誰的想法最安全？","says":[{"n":"小蓁","t":"聽從政府的撤離通知，先到安全的地方"},{"n":"阿旭","t":"上山看看溪水有多大"},{"n":"小哲","t":"在溪邊露營比較涼"}],"a":0,"why":"連續大雨容易發生土石流和溪水暴漲，要聽從撤離通知；上山或在溪邊都可能遇到危險。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-house-1', 'geo-house', 'mc', 1, '{"q":"早期漢人的房子多蓋成斜屋頂，主要是為了什麼？","opts":["讓雨水快點流走，不會積水","讓屋頂看起來比較高","讓鳥可以停在上面"],"a":0,"why":"臺灣雨多，斜屋頂讓雨水順著流下來，屋頂不會積水漏水；和外觀、鳥沒有關係。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-house-2', 'geo-house', 'multi', 2, '{"q":"哪些設計是為了適應臺灣多雨、炎熱的氣候？（選三個）","opts":["騎樓","遮雨棚","綠屋頂","在屋頂鋪雪板"],"a":[0,1,2],"why":"騎樓和遮雨棚讓人下雨天、大太陽也能走路；綠屋頂種植物可以吸水又隔熱。臺灣平地不下雪，不需要雪板。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-house-3', 'geo-house', 'tf', 2, '{"q":"「綠屋頂」是在屋頂種植物，可以吸收雨水，也能隔熱降溫。","a":true,"why":"植物和土壤能吸收雨水、減少積水，也能擋住陽光，讓屋子比較涼，是現代適應氣候的建築設計。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-house-4', 'geo-house', 'who', 3, '{"q":"學校為什麼要蓋「風雨球場」？誰說得對？","says":[{"n":"小晴","t":"下雨或大太陽時，也能在裡面上體育課"},{"n":"阿德","t":"為了讓球場比較貴"},{"n":"小嘉","t":"因為臺灣冬天會下大雪"}],"a":0,"why":"臺灣多雨又炎熱，有屋頂的風雨球場讓學生在雨天、烈日下也能活動，是因應氣候的設施；臺灣平地冬天不下雪。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-industry-1', 'geo-industry', 'cat', 1, '{"q":"這些地方的氣候適合發展什麼產業？","cats":["曬鹽","種百香果","種蘋果、水梨"],"cards":[{"t":"臺南沿海（冬天乾燥、陽光多）","c":0},{"t":"南投埔里（溫暖的盆地）","c":1},{"t":"南投仁愛山區（地勢高、涼爽）","c":2}],"why":"曬鹽需要乾燥和陽光，臺南沿海冬天適合；埔里盆地溫暖適合百香果；仁愛山區地勢高氣候涼，可以種溫帶水果。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-industry-2', 'geo-industry', 'mc', 2, '{"q":"為什麼南投仁愛的山區可以種蘋果、水梨這些溫帶水果？","opts":["地勢高、氣候涼爽","靠近海、海風很大","地勢低、天氣很熱"],"a":0,"why":"地勢越高氣溫越低，仁愛山區涼爽，適合種溫帶水果，冬天還能賞雪；靠海或炎熱的地方不適合。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-industry-3', 'geo-industry', 'tf', 2, '{"q":"臺灣沿海可以依季風的方向設置風力發電機發電。","a":true,"why":"臺灣冬天吹東北季風、夏天吹西南季風，沿海風力強又穩定，所以設置風力發電機，把風變成電。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-industry-4', 'geo-industry', 'who', 3, '{"q":"臺南的鹽田現在很多不再曬鹽了，變成什麼？誰說得對？","says":[{"n":"小筑","t":"轉型成休閒觀光，讓人認識曬鹽文化"},{"n":"阿任","t":"全部變成水庫"},{"n":"小敏","t":"改成滑雪場"}],"a":0,"why":"臺南早期利用冬季乾燥曬鹽，現在很多鹽田轉型成休閒觀光，保留鹽山讓人體驗；不會變成水庫或滑雪場。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-cold-1', 'geo-cold', 'mc', 1, '{"q":"冬天氣溫降到 10°C 以下，養殖的虱目魚可能凍死，這是哪一種災害？","opts":["寒害","旱災","水災"],"a":0,"why":"低溫損害農作物和漁業叫寒害，多在 12 月到隔年 2 月；旱災是缺水，水災是雨太多。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-cold-2', 'geo-cold', 'cat', 2, '{"q":"這些災害通常發生在什麼時候？","cats":["5～9 月","11 月～隔年 4 月","12 月～隔年 2 月"],"cards":[{"t":"水災、土石流","c":0},{"t":"旱災","c":1},{"t":"寒害","c":2}],"why":"梅雨和颱風在 5～9 月帶來水災土石流；11 月到隔年 4 月雨少容易旱災；12 月到 2 月寒流來容易寒害。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-cold-3', 'geo-cold', 'mc', 2, '{"q":"發生旱災、水不夠用時，農民可能怎麼做？","opts":["休耕，或改種比較不用水的甘薯","多種需要很多水的稻米","把河水全部引去魚塭"],"a":0,"why":"缺水時稻田沒水灌溉，農民會休耕或改種耐旱的甘薯；多種稻米只會更缺水。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('geo-cold-4', 'geo-cold', 'who', 3, '{"q":"寒流快來了，養虱目魚的阿伯該怎麼辦？誰的建議最好？","says":[{"n":"小蘭","t":"先把魚塭的水加深，或搭防寒棚"},{"n":"阿凱","t":"把魚塭的水放光"},{"n":"小賢","t":"什麼都不做，魚會自己游走"}],"a":0,"why":"虱目魚怕冷，加深水位或搭棚可以讓水溫不會降太快；把水放光或不處理，魚都可能凍死。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('isles-strait-4', 'isles-strait', 'cat', 3, '{"q":"早期居民怎麼適應氣候？配對看看。","cats":["澎湖菜宅","臺南竹籠茨"],"cards":[{"t":"用珊瑚礁石堆矮牆擋強風","c":0},{"t":"保護菜園不被東北季風吹壞","c":0},{"t":"竹子和茅草搭的房子","c":1},{"t":"淹水時可以整間扛走","c":1}],"why":"澎湖冬天東北季風強，用咾咕石圍成菜宅保護蔬菜；臺南竹籠茨用竹子茅草搭成，很輕，遇到洪水可以整間扛著移動。"}'::jsonb, '國小社會五年級上學期（康軒版）第二單元〈臺灣的地理特色與居民生活〉', 'draft'),
  ('ch1-cultures-4', 'ch1-cultures', 'mc', 2, '{"q":"臺東長濱的八仙洞遺址，史前人住在哪裡？","opts":["海邊的天然洞穴","高高的樹屋","石板蓋的大房子"],"a":0,"why":"八仙洞是舊石器時代的遺址，史前人住在海邊的天然洞穴，敲打石頭做工具，採集、狩獵、捕魚；石板屋是卑南遺址。"}'::jsonb, '國小社會五年級上學期（康軒版）史前文化；國立臺灣史前文化博物館', 'draft'),
  ('ch1-cultures-5', 'ch1-cultures', 'who', 3, '{"q":"十三行遺址挖到玻璃和瑪瑙飾品，這代表什麼？誰說得對？","says":[{"n":"小哲","t":"當時的人和外地有貿易交流"},{"n":"阿明","t":"十三行的人會自己做玻璃工廠"},{"n":"小靜","t":"這些是現代人不小心掉的"}],"a":0,"why":"玻璃、瑪瑙不是當地出產，表示十三行的人和外地有貿易往來；考古學家從出土的地層判斷是史前的東西。"}'::jsonb, '國小社會五年級上學期（康軒版）史前文化；國立臺灣史前文化博物館', 'draft'),
  ('abo-day-1', 'abo-day', 'mc', 1, '{"q":"政府訂哪一天為「原住民族日」？","opts":["8 月 1 日","12 月 18 日","10 月 10 日"],"a":0,"why":"8 月 1 日是原住民族日，紀念「原住民族」正名；12 月 18 日是移民節，10 月 10 日是國慶日。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('abo-day-2', 'abo-day', 'tf', 1, '{"q":"目前政府正式認定的臺灣原住民族共有 16 族。","a":true,"why":"政府正式認定的原住民族有 16 族，例如阿美族、泰雅族、排灣族、布農族、達悟族等，各有自己的語言和文化。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('abo-day-3', 'abo-day', 'cat', 2, '{"q":"這些原住民族群多分布在哪裡？","cats":["西部平原、丘陵","山地、東部、離島"],"cards":[{"t":"平埔族群","c":0},{"t":"達悟族（蘭嶼）","c":1},{"t":"布農族","c":1}],"why":"平埔族群住在西部平原丘陵，較早接觸漢人；達悟族在離島蘭嶼、布農族在中央山地，交通不便，保留較多傳統文化。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('abo-day-4', 'abo-day', 'who', 3, '{"q":"為什麼平埔族群的傳統語言和文化，比山地的族群保留得少？誰說得對？","says":[{"n":"小芸","t":"住在西部平原，較早接觸漢人，受影響比較深"},{"n":"阿傑","t":"因為平埔族群人比較少"},{"n":"小翰","t":"因為他們不喜歡自己的文化"}],"a":0,"why":"平埔族群分布在西部平原和丘陵，漢人來臺後最早接觸，語言和文化受影響最深；住在山地、東部、離島的族群交通不便，保留比較多傳統。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('abo-wisdom-1', 'abo-wisdom', 'mc', 1, '{"q":"阿美族的「巴拉告」是什麼？","opts":["在水裡替魚蝦打造的棲息地","一種打獵用的弓箭","豐年祭跳的舞"],"a":0,"why":"巴拉告是阿美族在溪流水塘裡用竹子、樹枝層層堆疊，讓魚蝦來住，需要時取一些、留一些，可以永續利用。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('abo-wisdom-2', 'abo-wisdom', 'tf', 2, '{"q":"賽德克族限制打獵的季節和區域，是為了讓動物能繁殖、不會被抓光。","a":true,"why":"限制狩獵季節和範圍，讓動物有時間長大繁殖，下一代才有獵物，是原住民族與自然共存的生態智慧。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('abo-wisdom-3', 'abo-wisdom', 'cat', 2, '{"q":"這些生態智慧是哪一族的？","cats":["阿美族","魯凱族","賽德克族"],"cards":[{"t":"巴拉告","c":0},{"t":"鬼湖傳說","c":1},{"t":"限制狩獵季節和區域","c":2}],"why":"巴拉告是阿美族的捕魚智慧；魯凱族用鬼湖傳說約束族人不隨便進入湖區；賽德克族限制狩獵季節和區域。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('abo-wisdom-4', 'abo-wisdom', 'who', 3, '{"q":"魯凱族流傳「鬼湖傳說」，讓族人不隨便靠近湖區。這有什麼作用？誰說得最好？","says":[{"n":"小伶","t":"用傳說約束大家，保護湖區的自然環境"},{"n":"阿翔","t":"只是嚇小孩的故事，沒有作用"},{"n":"小廷","t":"為了讓觀光客多來"}],"a":0,"why":"傳說讓族人敬畏、不隨意破壞，湖區的生態就被保護下來，是原住民族用文化約束行為、與自然共存的智慧。"}'::jsonb, '國小社會五年級上學期（康軒版）臺灣的原住民族；原住民族委員會', 'draft'),
  ('sea-why-1', 'sea-why', 'mc', 1, '{"q":"十五到十七世紀，歐洲人開拓新航路來亞洲，主要想找什麼？","opts":["香料、瓷器、絲綢","石油和煤礦","稻米和甘蔗苗"],"a":0,"why":"歐洲人想直接買到亞洲的香料、中國的瓷器和絲綢，所以發展航海技術找新航路；石油、煤礦是很後來才重要的。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('sea-why-2', 'sea-why', 'tf', 1, '{"q":"十六世紀葡萄牙人航行經過臺灣，稱臺灣為「福爾摩沙」，意思是美麗之島。","a":true,"why":"葡萄牙水手看到臺灣青翠的山，稱它「Ilha Formosa」，意思是美麗的島，所以臺灣又被叫做福爾摩沙。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('sea-why-3', 'sea-why', 'who', 2, '{"q":"為什麼大航海時代的臺灣會受到重視？誰說得對？","says":[{"n":"小恩","t":"位在中國、日本、東南亞之間的航路上，適合當貿易中繼站"},{"n":"阿華","t":"因為臺灣有很多香料"},{"n":"小宜","t":"因為臺灣離歐洲最近"}],"a":0,"why":"臺灣剛好在中國、日本、東南亞往來的海上航路中間，可以當轉運貨物的中繼站；臺灣不產香料，離歐洲也很遠。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('sea-why-4', 'sea-why', 'order', 3, '{"q":"把大航海時代的事照先後排好。","steps":["葡萄牙人經過臺灣，稱它福爾摩沙","荷蘭人在臺南安平登陸","鄭成功趕走荷蘭人"],"why":"十六世紀葡萄牙人先經過臺灣；1624 年荷蘭人在臺南安平登陸；1661 年鄭成功攻臺，隔年荷蘭人離開。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('sea-dutch-1', 'sea-dutch', 'mc', 1, '{"q":"荷蘭人在臺南蓋的普羅民遮城，就是今天的哪裡？","opts":["赤崁樓","紅毛城","億載金城"],"a":0,"why":"荷蘭人在臺南蓋了熱蘭遮城（今安平古堡）和普羅民遮城（今赤崁樓）；紅毛城在淡水，是西班牙人最早蓋的。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('sea-dutch-2', 'sea-dutch', 'tf', 2, '{"q":"荷蘭人欺壓漢人，引發 1652 年的郭懷一事件。","a":true,"why":"荷蘭人對漢人收重稅、管理嚴苛，漢人郭懷一帶頭反抗，就是郭懷一事件，最後被荷蘭人鎮壓。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('sea-dutch-3', 'sea-dutch', 'multi', 2, '{"q":"荷蘭人引進臺灣的有哪些？（選三個）","opts":["黃牛","芒果","蓮霧","鳳梨酥"],"a":[0,1,2],"why":"荷蘭人引進黃牛幫忙耕田，也帶來芒果、蓮霧等作物；鳳梨酥是很後來的臺灣點心。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('sea-dutch-4', 'sea-dutch', 'mc', 3, '{"q":"臺灣有些地方的名字有「紅毛」兩個字，跟哪一群人有關？","opts":["荷蘭人","日本人","鄭成功的軍隊"],"a":0,"why":"當時漢人稱荷蘭人為「紅毛」，所以留下紅毛港、紅毛城這類地名；和日本人、鄭氏軍隊無關。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('sea-spain-1', 'sea-spain', 'mc', 1, '{"q":"西班牙人 1626 年在臺灣的哪裡建立據點？","opts":["北部的基隆、淡水","南部的臺南、高雄","東部的花蓮、臺東"],"a":0,"why":"西班牙人佔領北部的基隆和淡水，蓋了聖薩爾瓦多城和聖多明哥城；荷蘭人在南部的臺南。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('sea-spain-2', 'sea-spain', 'tf', 2, '{"q":"西班牙人一直在臺灣待到鄭成功來，才被趕走。","a":false,"why":"西班牙人在 1642 年就被荷蘭人趕出北臺灣，鄭成功 1661 年來的時候趕走的是荷蘭人。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('sea-spain-3', 'sea-spain', 'cat', 2, '{"q":"這些是哪一群人留下的？","cats":["荷蘭人","西班牙人"],"cards":[{"t":"新港文書","c":0},{"t":"熱蘭遮城","c":0},{"t":"三貂角地名","c":1},{"t":"諸聖教堂","c":1}],"why":"新港文書、熱蘭遮城是荷蘭人留下的；三貂角（來自 Santiago）地名和傳天主教的諸聖教堂，是西班牙人留下的。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('sea-spain-4', 'sea-spain', 'who', 3, '{"q":"關於西班牙人在臺灣，誰說得對？","says":[{"n":"小安","t":"在北臺灣傳天主教，留下三貂角這樣的地名"},{"n":"阿凱","t":"在臺南蓋了赤崁樓"},{"n":"小雨","t":"用羅馬字母寫出新港文書"}],"a":0,"why":"西班牙人在北部傳天主教、留下三貂角等地名；赤崁樓和新港文書都是荷蘭人在南部留下的。"}'::jsonb, '國小社會五年級上學期（康軒版）〈大航海時代的臺灣〉；文化部《臺灣大百科全書》', 'draft'),
  ('inq-steps-1', 'inq-steps', 'order', 1, '{"q":"想推薦一個臺灣景點給外國朋友，把探究的四個步驟排好。","steps":["發現問題：要推薦哪裡？為什麼？","蒐集資料：上網、去圖書館查","整理分析：把特色、歷史、問題整理成表","行動省思：提出解決辦法、想想未來"],"why":"探究四步驟是發現問題、蒐集資料、整理分析、行動省思。要先知道問什麼才能查資料，資料整理好才能提出辦法。"}'::jsonb, '國小社會（康軒版）家鄉與臺灣的觀光；各國家公園管理處公開資料', 'draft'),
  ('inq-steps-2', 'inq-steps', 'mc', 2, '{"q":"整理景點資料時，下面哪一項最適合放進表格？","opts":["政府怎麼維護、遇到什麼問題","自己最喜歡的卡通人物","同學的電話號碼"],"a":0,"why":"景點資料表通常包含特色、歷史、政府怎麼維護、面臨的問題；卡通人物和電話號碼和景點探究無關。"}'::jsonb, '國小社會（康軒版）家鄉與臺灣的觀光；各國家公園管理處公開資料', 'draft'),
  ('inq-steps-3', 'inq-steps', 'tf', 2, '{"q":"探究報告寫完景點的問題就結束了，不用提出解決辦法。","a":false,"why":"探究的最後一步是行動省思：針對問題提出解決策略，並想想未來可以怎麼做，所以不能只寫問題。"}'::jsonb, '國小社會（康軒版）家鄉與臺灣的觀光；各國家公園管理處公開資料', 'draft'),
  ('inq-steps-4', 'inq-steps', 'who', 3, '{"q":"太魯閣遊客太多又有落石，誰提出的辦法最好？","says":[{"n":"小羽","t":"人多的步道總量管制，落石區戴安全帽"},{"n":"阿駿","t":"把步道全部鋪水泥"},{"n":"小蘋","t":"禁止所有人去，關掉國家公園"}],"a":0,"why":"總量管制和戴安全帽能兼顧安全和環境；鋪水泥會破壞景觀也擋不住落石，全部關掉則讓大家失去認識自然的機會。"}'::jsonb, '國小社會（康軒版）家鄉與臺灣的觀光；各國家公園管理處公開資料', 'draft'),
  ('sci-camo-1', 'sci-camo', 'mc', 1, '{"q":"枯葉蝶收起翅膀時像什麼，讓天敵找不到牠？","opts":["一片枯葉","一朵紅花","一顆石頭"],"a":0,"why":"枯葉蝶翅膀外面是咖啡色的，還有像葉脈的紋路，收起來就像一片枯葉，天敵很難發現牠。這種讓自己看起來像別的東西的本領叫「偽裝」。"}'::jsonb, '國小自然五年級上學期（康軒版）〈動物世界〉；時光祕境島圖鑑「枯葉蝶」「螞蟻」', 'draft'),
  ('sci-camo-2', 'sci-camo', 'tf', 2, '{"q":"枯葉蝶停在落葉堆裡不動，比較不容易被天敵發現。","a":true,"why":"枯葉蝶收起翅膀就像一片枯葉，停在落葉堆裡又不動，天敵很難分出哪個是牠，所以比較安全。動起來反而容易被看到。"}'::jsonb, '國小自然五年級上學期（康軒版）〈動物世界〉；時光祕境島圖鑑「枯葉蝶」「螞蟻」', 'draft'),
  ('sci-camo-3', 'sci-camo', 'who', 3, '{"q":"為什麼很多動物身上的顏色，和住的地方很像？誰說得對？","says":[{"n":"斑斑","t":"這樣比較不容易被天敵或獵物發現"},{"n":"小樹","t":"因為牠們喜歡那個顏色"},{"n":"阿光","t":"因為顏色會被太陽曬掉"}],"a":0,"why":"身上的顏色和住的地方很像，叫「保護色」。這樣比較不容易被天敵看到，也能偷偷接近獵物。顏色不是因為喜歡，也不是被太陽曬掉的。"}'::jsonb, '國小自然五年級上學期（康軒版）〈動物世界〉；時光祕境島圖鑑「枯葉蝶」「螞蟻」', 'draft'),
  ('sci-ant-team-1', 'sci-ant-team', 'cat', 2, '{"q":"螞蟻窩裡，誰負責什麼工作？","cats":["蟻后","工蟻","兵蟻"],"cards":[{"t":"產卵","c":0},{"t":"找食物、搬東西","c":1},{"t":"照顧卵和幼蟲","c":1},{"t":"守住蟻窩","c":2}],"why":"螞蟻窩分工很清楚：蟻后專門產卵；工蟻最多，要找食物、搬東西、照顧卵和幼蟲；兵蟻的頭和大顎比較大，負責守住蟻窩。"}'::jsonb, '國小自然五年級上學期（康軒版）〈動物世界〉；時光祕境島圖鑑「枯葉蝶」「螞蟻」', 'draft'),
  ('sci-ant-team-2', 'sci-ant-team', 'tf', 1, '{"q":"螞蟻是群體生活、分工合作的動物。","a":true,"why":"螞蟻是群體生活的動物，一個蟻窩裡有蟻后、工蟻、兵蟻，各自負責不同的工作，合作讓整個家族活下去。"}'::jsonb, '國小自然五年級上學期（康軒版）〈動物世界〉；時光祕境島圖鑑「枯葉蝶」「螞蟻」', 'draft'),
  ('sci-ant-team-3', 'sci-ant-team', 'mc', 2, '{"q":"一塊很大的餅乾，螞蟻怎麼把它搬回窩？","opts":["很多隻工蟻一起搬","蟻后自己搬","等餅乾自己滾進去"],"a":0,"why":"一隻螞蟻搬不動大餅乾，工蟻會找來很多同伴一起合作搬回窩。蟻后只負責產卵，不會出來搬東西。"}'::jsonb, '國小自然五年級上學期（康軒版）〈動物世界〉；時光祕境島圖鑑「枯葉蝶」「螞蟻」', 'draft'),
  ('sci-ant-talk-1', 'sci-ant-talk', 'multi', 2, '{"q":"螞蟻用哪些方法傳遞消息？（選兩個）","opts":["觸角互相碰觸","在地上留下氣味","大聲叫","揮手打招呼"],"a":[0,1],"why":"螞蟻沒辦法大聲說話，也不會揮手。牠們用觸角互相碰一碰來交換消息，也會在地上留下氣味，同伴聞著氣味就知道路。"}'::jsonb, '國小自然五年級上學期（康軒版）〈動物世界〉；時光祕境島圖鑑「枯葉蝶」「螞蟻」', 'draft'),
  ('sci-ant-talk-2', 'sci-ant-talk', 'mc', 3, '{"q":"一排螞蟻走成一條線去找食物，最可能是因為什麼？","opts":["跟著前面同伴留下的氣味走","牠們看得到很遠的食物","有人在前面帶路"],"a":0,"why":"找到食物的螞蟻回窩時會在地上留下氣味，後面的同伴跟著氣味走，就排成一條線。螞蟻的眼睛看不遠，也沒有誰在前面帶路。"}'::jsonb, '國小自然五年級上學期（康軒版）〈動物世界〉；時光祕境島圖鑑「枯葉蝶」「螞蟻」', 'draft'),
  ('sci-rust-why-1', 'sci-rust-why', 'multi', 2, '{"q":"鐵要碰到哪些東西，久了才會生鏽？（選兩個）","opts":["水","空氣","沙子","光"],"a":[0,1],"why":"鐵要「同時」碰到水和空氣（裡面的氧氣），久了才會生鏽。只有其中一樣不容易生鏽；沙子和光不是生鏽的原因。"}'::jsonb, '國小自然五年級上學期（康軒版）〈燃燒與生鏽〉；時光祕境島圖鑑「生鏽」', 'draft'),
  ('sci-rust-why-2', 'sci-rust-why', 'mc', 2, '{"q":"同樣的鐵釘，放在哪裡最快生鏽？","opts":["又濕又鹹的海邊","乾燥的抽屜裡","密封的乾燥罐裡"],"a":0,"why":"生鏽需要水和空氣，海邊又濕、空氣裡又有鹽分，鹽會讓鐵鏽得更快，所以海邊的鐵最快生鏽。乾燥的地方水少，比較不會鏽。"}'::jsonb, '國小自然五年級上學期（康軒版）〈燃燒與生鏽〉；時光祕境島圖鑑「生鏽」', 'draft'),
  ('sci-rust-why-3', 'sci-rust-why', 'tf', 1, '{"q":"放在乾燥地方的鐵，比放在潮濕地方的鐵容易生鏽。","a":false,"why":"生鏽需要水，潮濕的地方水氣多，鐵比較容易生鏽；乾燥的地方水少，反而比較不會鏽。所以這句話說反了。"}'::jsonb, '國小自然五年級上學期（康軒版）〈燃燒與生鏽〉；時光祕境島圖鑑「生鏽」', 'draft'),
  ('sci-rust-stop-1', 'sci-rust-stop', 'multi', 2, '{"q":"下面哪些方法可以防止鐵生鏽？（選兩個以上）","opts":["保持乾燥","塗一層油","上油漆","常常泡在鹽水裡"],"a":[0,1,2],"why":"防鏽的祕訣就是把鐵和水、空氣隔開：保持乾燥、塗一層油、上油漆都可以。泡在鹽水裡反而會讓鐵鏽得更快。"}'::jsonb, '國小自然五年級上學期（康軒版）〈燃燒與生鏽〉；時光祕境島圖鑑「生鏽」', 'draft'),
  ('sci-rust-stop-2', 'sci-rust-stop', 'order', 3, '{"q":"鐵門有點濕又開始生鏽，排出修理的順序。","steps":["用乾布把水擦乾","把鏽刷掉","塗上油漆把鐵包起來"],"why":"要先用乾布把水擦乾，再把鏽刷掉，最後才塗油漆把鐵包起來。如果在濕的、有鏽的鐵上直接塗油漆，水和鏽會被包在裡面，還是會繼續鏽。"}'::jsonb, '國小自然五年級上學期（康軒版）〈燃燒與生鏽〉；時光祕境島圖鑑「生鏽」', 'draft'),
  ('sci-rust-stop-3', 'sci-rust-stop', 'who', 2, '{"q":"腳踏車的鏈條要怎麼保養才不容易生鏽？誰說得對？","says":[{"n":"鐵叔","t":"擦乾淨以後上一點油"},{"n":"小海","t":"每天用水沖"},{"n":"阿浪","t":"放在雨裡比較乾淨"}],"a":0,"why":"鏈條擦乾淨後上一點油，油會把鐵和水、空氣隔開，就不容易生鏽。每天用水沖或放在雨裡，鐵一直碰到水，反而鏽得更快。"}'::jsonb, '國小自然五年級上學期（康軒版）〈燃燒與生鏽〉；時光祕境島圖鑑「生鏽」', 'draft'),
  ('sci-vibrate-1', 'sci-vibrate', 'tf', 1, '{"q":"聲音是物體振動產生的。","a":true,"why":"所有聲音都是東西振動產生的：敲鼓時鼓皮在振動、撥弦時弦在振動、說話時喉嚨裡的聲帶在振動。振動停了，聲音就停了。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉；時光祕境島圖鑑「聲音」', 'draft'),
  ('sci-vibrate-2', 'sci-vibrate', 'mc', 2, '{"q":"敲完音叉，把它輕輕放進水裡，會看到什麼？","opts":["水花被振動濺起來","水變成熱水","什麼都不會發生"],"a":0,"why":"音叉發出聲音時，兩支叉子在很快地振動，眼睛看不出來。放進水裡，振動會把水打得濺起水花，證明發聲的東西在振動。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉；時光祕境島圖鑑「聲音」', 'draft'),
  ('sci-vibrate-3', 'sci-vibrate', 'mc', 2, '{"q":"用手按住正在響的鼓皮，聲音會怎樣？","opts":["聲音停下來","聲音變更大","聲音變更高"],"a":0,"why":"聲音是振動產生的。用手按住鼓皮，鼓皮就不能振動，聲音也就停了；不會變大聲，也不會變高。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉；時光祕境島圖鑑「聲音」', 'draft'),
  ('sci-pitch-1', 'sci-pitch', 'cloze', 2, '{"q":"調樂器的聲音。","text":"弦拉得越{0}，聲音越高；鼓皮繃得越{1}，聲音也越高。","blanks":[{"opts":["緊","鬆"],"a":0},{"opts":["緊","鬆"],"a":0}],"why":"弦拉得越緊、鼓皮繃得越緊，振動得越快，聲音就越高；放鬆的話振動變慢，聲音就變低。所以兩格都填「緊」。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉；時光祕境島圖鑑「聲音」', 'draft'),
  ('sci-pitch-2', 'sci-pitch', 'order', 3, '{"q":"三個一樣的玻璃瓶裝了不同多的水，用筷子敲。從最低的聲音排到最高。","steps":["水最多的瓶子","水一半的瓶子","水最少的瓶子"],"why":"用筷子敲瓶子時，是瓶子和水一起振動。水越多，振動越慢，聲音越低；水越少，振動越快，聲音越高。所以從低到高是：水最多→一半→最少。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉；時光祕境島圖鑑「聲音」', 'draft'),
  ('sci-pitch-3', 'sci-pitch', 'tf', 2, '{"q":"用筷子敲裝水的玻璃瓶，水越多，聲音越高。","a":false,"why":"用筷子「敲」瓶子時，是瓶子和裡面的水一起振動，水越多振動越慢，聲音越低。所以水越多聲音越「低」，這句話說反了。（用嘴「吹」瓶口時剛好相反。）"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉；時光祕境島圖鑑「聲音」', 'draft'),
  ('sci-noise-1', 'sci-noise', 'multi', 2, '{"q":"下面哪些方法可以減少噪音？（選兩個以上）","opts":["掛上隔音布、關窗","離聲音來源遠一點","晚上把音量轉小","把喇叭對準鄰居"],"a":[0,1,2],"why":"減少噪音有三招：在聲音傳過來的路上擋住（隔音布、關窗）、離聲音遠一點、從源頭把音量轉小。把喇叭對準鄰居只會讓噪音更嚴重。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉；時光祕境島圖鑑「聲音」', 'draft'),
  ('sci-noise-2', 'sci-noise', 'mc', 1, '{"q":"什麼樣的聲音是「噪音」？","opts":["讓人覺得吵、不舒服的聲音","所有很高的聲音","所有音樂的聲音"],"a":0,"why":"噪音不是看聲音高不高，而是看會不會讓人覺得吵、不舒服。好聽的音樂如果太大聲或半夜放，吵到別人也會變成噪音。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉；時光祕境島圖鑑「聲音」', 'draft'),
  ('sci-sun-1', 'sci-sun', 'cloze', 1, '{"q":"太陽在天空的位置。","text":"太陽早上從{0}邊升起，傍晚從{1}邊落下。","blanks":[{"opts":["東","西","南"],"a":0},{"opts":["東","西","北"],"a":1}],"why":"因為地球由西往東自轉，我們看起來太陽每天從東邊升起，經過天空，傍晚從西邊落下，這叫「東升西落」。"}'::jsonb, '國小自然五年級上學期（康軒版）〈神祕的天空〉；時光祕境島圖鑑「太陽與影子」', 'draft'),
  ('sci-sun-2', 'sci-sun', 'mc', 2, '{"q":"一天裡，太陽什麼時候在天空最高的地方？","opts":["中午","早上","傍晚"],"a":0,"why":"太陽早上從東邊升起時比較低，越接近中午爬得越高，中午最高，下午又慢慢變低，傍晚從西邊落下。"}'::jsonb, '國小自然五年級上學期（康軒版）〈神祕的天空〉；時光祕境島圖鑑「太陽與影子」', 'draft'),
  ('sci-sun-3', 'sci-sun', 'order', 2, '{"q":"排出一天裡太陽的位置變化。","steps":["從東邊升起","中午在天空最高","從西邊落下"],"why":"一天裡太陽的路線是：早上從東邊升起→中午爬到天空最高的地方→傍晚從西邊落下。照「東→高→西」排就對了。"}'::jsonb, '國小自然五年級上學期（康軒版）〈神祕的天空〉；時光祕境島圖鑑「太陽與影子」', 'draft'),
  ('sci-shadow-1', 'sci-shadow', 'mc', 2, '{"q":"早上太陽在東邊，地上的影子會倒向哪一邊？","opts":["西邊","東邊","影子不見了"],"a":0,"why":"影子一定在太陽的「反方向」，因為光被身體擋住，後面才有影子。早上太陽在東邊，影子就倒向西邊。"}'::jsonb, '國小自然五年級上學期（康軒版）〈神祕的天空〉；時光祕境島圖鑑「太陽與影子」', 'draft'),
  ('sci-shadow-2', 'sci-shadow', 'tf', 2, '{"q":"一天裡，中午的影子最短。","a":true,"why":"太陽越高，影子越短。中午太陽在天空最高的地方，影子最短；早上和傍晚太陽低低的，影子會拉得很長。"}'::jsonb, '國小自然五年級上學期（康軒版）〈神祕的天空〉；時光祕境島圖鑑「太陽與影子」', 'draft'),
  ('sci-shadow-3', 'sci-shadow', 'who', 3, '{"q":"在臺灣，中午時影子大多朝向哪一邊？誰說得對？","says":[{"n":"帝雉台長","t":"大多朝向北邊，因為太陽在南邊的天空"},{"n":"小星","t":"朝向東邊"},{"n":"阿月","t":"中午沒有影子"}],"a":0,"why":"臺灣在北回歸線附近，一年裡大部分的日子，中午太陽在南邊的天空。影子在太陽的反方向，所以中午的影子大多朝向北邊。"}'::jsonb, '國小自然五年級上學期（康軒版）〈神祕的天空〉；時光祕境島圖鑑「太陽與影子」', 'draft'),
  ('sci-sundial-1', 'sci-sundial', 'mc', 2, '{"q":"日晷是看什麼來知道時間？","opts":["影子的位置","星星的顏色","風吹的方向"],"a":0,"why":"太陽在天空移動，影子也跟著移動。日晷就是看影子落在哪一個刻度，來知道現在幾點，跟星星、風都沒關係。"}'::jsonb, '國小自然五年級上學期（康軒版）〈神祕的天空〉；時光祕境島圖鑑「太陽與影子」', 'draft'),
  ('sci-sundial-2', 'sci-sundial', 'mc', 3, '{"q":"日晷的影子從西邊慢慢轉到東邊，表示時間怎麼過？","opts":["從早上到下午","從下午到早上","時間沒有變"],"a":0,"why":"影子在太陽的反方向：早上太陽在東邊，影子朝西；下午太陽移到西邊，影子朝東。所以影子從西轉到東，表示時間從早上走到下午。"}'::jsonb, '國小自然五年級上學期（康軒版）〈神祕的天空〉；時光祕境島圖鑑「太陽與影子」', 'draft'),
  ('sci-burn-need-1', 'sci-burn-need', 'multi', 1, '{"q":"燃燒一定要有哪三樣東西？（選三個）","opts":["可以燒的東西","空氣（氧氣）","夠高的溫度","很多水"],"a":[0,1,2],"why":"燃燒要可以燒的東西、空氣（裡面的氧氣）和夠高的溫度，三樣都有才燒得起來。水反而會讓溫度變低，把火澆熄。"}'::jsonb, '國小自然五年級上學期（康軒版）〈燃燒與生鏽〉；時光祕境島圖鑑「燃燒」（海港燈塔）；內政部消防署居家防火宣導', 'draft'),
  ('sci-burn-need-2', 'sci-burn-need', 'mc', 2, '{"q":"燈室裡木柴點著了，可是窗戶關得密不通風，火一下就熄了。少了什麼？","opts":["空氣","木柴","溫度"],"a":0,"why":"窗戶關緊，新鮮空氣進不來，裡面的氧氣燒完火就悶熄了。打開通風窗讓空氣進來，火才會越燒越旺。"}'::jsonb, '國小自然五年級上學期（康軒版）〈燃燒與生鏽〉；時光祕境島圖鑑「燃燒」（海港燈塔）；內政部消防署居家防火宣導', 'draft'),
  ('sci-burn-need-3', 'sci-burn-need', 'who', 2, '{"q":"用放大鏡把陽光聚在木柴上，為什麼能點火？誰說得對？","says":[{"n":"海鷗爺爺","t":"光聚成一個小點，那裡變得很熱"},{"n":"斑斑","t":"放大鏡會自己冒出火來"},{"n":"鐵叔","t":"陽光把木柴變成油"}],"a":0,"why":"放大鏡把很大一片陽光集中到一個小點，那一點的溫度一直升高，到了夠熱的程度木柴就燒起來了。千萬不要用放大鏡看太陽，眼睛會受傷。"}'::jsonb, '國小自然五年級上學期（康軒版）〈燃燒與生鏽〉；時光祕境島圖鑑「燃燒」（海港燈塔）；內政部消防署居家防火宣導', 'draft'),
  ('sci-burn-out-1', 'sci-burn-out', 'cat', 1, '{"q":"這些滅火方法，各是拿掉燃燒的哪一樣？","cats":["可以燒的東西","空氣","溫度"],"cards":[{"t":"把旁邊的箱子搬開","c":0},{"t":"撒沙子蓋住","c":1},{"t":"蓋上鍋蓋","c":1},{"t":"潑水讓它變涼","c":2}],"why":"滅火就是拿掉燃燒三樣東西中的一樣：搬開東西是拿走可以燒的；沙子、鍋蓋把火蓋住，空氣進不去；潑水讓溫度降下來。"}'::jsonb, '國小自然五年級上學期（康軒版）〈燃燒與生鏽〉；時光祕境島圖鑑「燃燒」（海港燈塔）；內政部消防署居家防火宣導', 'draft'),
  ('sci-burn-out-2', 'sci-burn-out', 'mc', 2, '{"q":"炸東西的油鍋著火了，最好怎麼做？","opts":["蓋上鍋蓋","潑一盆水","用扇子搧"],"a":0,"why":"油鍋潑水，水碰到熱油會讓油噴出來，火反而更大。蓋上鍋蓋把空氣隔開，火就悶熄了。搧風會送更多空氣進去，火更旺。"}'::jsonb, '國小自然五年級上學期（康軒版）〈燃燒與生鏽〉；時光祕境島圖鑑「燃燒」（海港燈塔）；內政部消防署居家防火宣導', 'draft'),
  ('sci-burn-out-3', 'sci-burn-out', 'tf', 2, '{"q":"森林大火時，先把火旁邊的樹木砍掉清出一條空地，可以讓火燒不過去。","a":true,"why":"這是拿走「可以燒的東西」：火燒到空地沒有東西可以燒，就停下來了，和海港搬開貨箱是一樣的道理。"}'::jsonb, '國小自然五年級上學期（康軒版）〈燃燒與生鏽〉；時光祕境島圖鑑「燃燒」（海港燈塔）；內政部消防署居家防火宣導', 'draft'),
  ('sci-burn-out-4', 'sci-burn-out', 'mc', 3, '{"q":"實驗課用完酒精燈，要怎麼熄滅？","opts":["用燈罩蓋上","用嘴巴吹熄","倒水進去"],"a":0,"why":"燈罩一蓋，裡面的空氣用完火就熄了，這是隔絕空氣。用嘴吹火焰可能竄出來，倒水會讓燈破裂，都很危險。"}'::jsonb, '國小自然五年級上學期（康軒版）〈燃燒與生鏽〉；時光祕境島圖鑑「燃燒」（海港燈塔）；內政部消防署居家防火宣導', 'draft'),
  ('sci-light-line-1', 'sci-light-line', 'tf', 1, '{"q":"光是走直線的，東西擋住光，後面就會出現影子。","a":true,"why":"光一直往前直直走，碰到不透明的東西過不去，東西後面照不到光的地方就是影子。皮影戲就是用這個道理。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉光的特性；時光祕境島圖鑑「光」（光的魔術舞台）', 'draft'),
  ('sci-light-line-2', 'sci-light-line', 'mc', 2, '{"q":"演皮影戲時，想讓布幕上的影子變大，戲偶要怎麼移？","opts":["往燈那邊靠近","往布幕那邊靠近","放在哪裡都一樣大"],"a":0,"why":"戲偶離燈越近，擋住的光越多，影子就越大；越靠近布幕，影子越小、越清楚。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉光的特性；時光祕境島圖鑑「光」（光的魔術舞台）', 'draft'),
  ('sci-light-line-3', 'sci-light-line', 'cloze', 2, '{"q":"影子的大小。","text":"手電筒照著玩偶，玩偶離燈越{0}，牆上的影子越大；離燈越{1}，影子越小。","blanks":[{"opts":["近","遠"],"a":0},{"opts":["近","遠"],"a":1}],"why":"靠近燈的時候，玩偶擋住的光線範圍很大，所以影子大；離燈遠，擋住的少，影子就小。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉光的特性；時光祕境島圖鑑「光」（光的魔術舞台）', 'draft'),
  ('sci-refract-1', 'sci-refract', 'tf', 1, '{"q":"光從空氣斜斜照進水裡時，會在水面轉彎。","a":true,"why":"光從空氣進到水裡，前進的方向會偏折，這叫「折射」。舞台水缸裡的光就是因為這樣才能照到寶石。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉光的特性；時光祕境島圖鑑「光」（光的魔術舞台）', 'draft'),
  ('sci-refract-2', 'sci-refract', 'mc', 2, '{"q":"把筷子斜斜插進一杯水裡，從旁邊看會怎樣？","opts":["筷子在水面的地方好像折斷了","筷子變成兩支","筷子在水裡不見了"],"a":0,"why":"水裡那一段筷子的光，出水面時轉了彎才進到眼睛，所以看起來位置偏了，好像在水面折斷。筷子其實是直的。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉光的特性；時光祕境島圖鑑「光」（光的魔術舞台）', 'draft'),
  ('sci-refract-3', 'sci-refract', 'who', 3, '{"q":"站在池邊看水底，覺得水很淺。為什麼不能直接跳下去？誰說得對？","says":[{"n":"團長","t":"光會轉彎，水看起來比實際還淺"},{"n":"小樹蛙","t":"水底的石頭會變大"},{"n":"斑斑","t":"水會把光吃掉"}],"a":0,"why":"水底的光出水面時會折射，讓池底看起來比實際更高，水就顯得比較淺。所以看起來淺的水也可能很深，不能隨便跳下去。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉光的特性；時光祕境島圖鑑「光」（光的魔術舞台）', 'draft'),
  ('sci-lens-1', 'sci-lens', 'mc', 1, '{"q":"放大鏡的鏡片長什麼樣子？","opts":["中間厚、邊緣薄","中間薄、邊緣厚","整片一樣厚"],"a":0,"why":"放大鏡是中間厚、邊緣薄的凸透鏡，光穿過時會往中間集中，所以能把東西放大，也能把陽光聚成一點。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉光的特性；時光祕境島圖鑑「光」（光的魔術舞台）', 'draft'),
  ('sci-lens-2', 'sci-lens', 'mc', 2, '{"q":"用放大鏡看紙條上的小字，把放大鏡慢慢拿離紙條遠一點，字會怎樣？","opts":["先變大，太遠會糊掉","一直變小","大小都不變"],"a":0,"why":"放大鏡靠近紙時，字會隨距離變大；拿得太遠超過一個距離，字就會糊掉，再遠還會上下顛倒。舞台道具箱的密碼就是這樣看清楚的。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉光的特性；時光祕境島圖鑑「光」（光的魔術舞台）', 'draft'),
  ('sci-lens-3', 'sci-lens', 'multi', 2, '{"q":"放大鏡可以用來做什麼？（選兩個）","opts":["看清楚很小的字","把陽光聚在一點變熱","直接看太陽","讓聲音變大"],"a":[0,1],"why":"放大鏡能放大小東西，也能把陽光聚成很熱的小點（燈塔就是這樣點火）。但絕對不可以拿它看太陽，會傷眼睛；它也和聲音沒有關係。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉光的特性；時光祕境島圖鑑「光」（光的魔術舞台）', 'draft'),
  ('sci-prism-1', 'sci-prism', 'mc', 1, '{"q":"白光穿過三稜鏡以後，會變成什麼？","opts":["分成七種顏色","變成一道黑光","全部變成紅色"],"a":0,"why":"白光其實是很多顏色的光混在一起，穿過三稜鏡時每種顏色轉彎的程度不一樣，就分開成紅、橙、黃、綠、藍、靛、紫。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉光的特性；時光祕境島圖鑑「光」（光的魔術舞台）', 'draft'),
  ('sci-prism-2', 'sci-prism', 'tf', 2, '{"q":"天上的彩虹，是陽光穿過空中的小水滴，被分成很多顏色。","a":true,"why":"雨後空中有很多小水滴，每一顆都像小小的三稜鏡，把陽光分成七種顏色，就是彩虹。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉光的特性；時光祕境島圖鑑「光」（光的魔術舞台）', 'draft'),
  ('sci-prism-3', 'sci-prism', 'who', 3, '{"q":"雨剛停、太陽出來了，要看彩虹該面向哪裡？誰說得對？","says":[{"n":"團長","t":"背對太陽，看太陽對面的天空"},{"n":"阿光","t":"直直看著太陽"},{"n":"小海","t":"看地上的水坑"}],"a":0,"why":"彩虹出現在太陽的對面，要背對太陽才看得到。直接看太陽會傷眼睛，也看不到彩虹。"}'::jsonb, '國小自然五年級上學期（康軒版）〈探索聲光世界〉光的特性；時光祕境島圖鑑「光」（光的魔術舞台）', 'draft'),
  ('sci-pond-plant-1', 'sci-pond-plant', 'cat', 1, '{"q":"把水生植物放到它住的地方。","cats":["挺出水面","葉子浮在水面","整棵漂著","整棵泡在水裡"],"cards":[{"t":"荷花","c":0},{"t":"睡蓮","c":1},{"t":"布袋蓮","c":2},{"t":"水蘊草","c":3}],"why":"荷花莖硬，把葉和花撐出水面；睡蓮的葉子浮在水面、根在泥裡；布袋蓮整棵漂著；水蘊草整棵泡在水裡。"}'::jsonb, '國小自然四年級上學期（康軒版）〈水生生物與環境〉；時光祕境島圖鑑「水生植物與魚」（池塘）', 'draft'),
  ('sci-pond-plant-2', 'sci-pond-plant', 'mc', 2, '{"q":"布袋蓮為什麼能整棵漂在水面上？","opts":["葉柄鼓鼓的，裡面有空氣","根很長抓住池底","葉子是塑膠做的"],"a":0,"why":"布袋蓮的葉柄膨大像小氣球，裡面充滿空氣，所以整棵能浮在水面，根垂在水中，不用抓住池底。"}'::jsonb, '國小自然四年級上學期（康軒版）〈水生生物與環境〉；時光祕境島圖鑑「水生植物與魚」（池塘）', 'draft'),
  ('sci-pond-plant-3', 'sci-pond-plant', 'tf', 2, '{"q":"水蘊草拿出水面就軟趴趴的，因為它是整棵泡在水裡生長的沉水植物。","a":true,"why":"水蘊草的莖又細又軟，靠水的浮力撐著，所以一離開水就倒下來。它在水裡行光合作用，還會冒出小氣泡。"}'::jsonb, '國小自然四年級上學期（康軒版）〈水生生物與環境〉；時光祕境島圖鑑「水生植物與魚」（池塘）', 'draft'),
  ('sci-pond-plant-4', 'sci-pond-plant', 'who', 3, '{"q":"睡蓮要種在多深的地方？誰說得對？","says":[{"n":"小樹蛙","t":"不深不淺，葉子浮得到水面、根抓得到泥巴"},{"n":"斑斑","t":"越深越好"},{"n":"小魚","t":"種在岸上就好"}],"a":0,"why":"睡蓮的根要抓在池底泥巴裡，葉子又要浮在水面。太淺葉子會擱在泥上，太深根碰不到底，所以要不深不淺。"}'::jsonb, '國小自然四年級上學期（康軒版）〈水生生物與環境〉；時光祕境島圖鑑「水生植物與魚」（池塘）', 'draft'),
  ('sci-fish-1', 'sci-fish', 'mc', 1, '{"q":"魚在水裡用什麼呼吸？","opts":["鰓","肺","尾巴"],"a":0,"why":"魚頭的兩邊有鰓，嘴巴喝水、水從鰓流出去時，鰓就把水裡的氧氣吸進身體。人用肺呼吸，所以不能在水裡呼吸。"}'::jsonb, '國小自然四年級上學期（康軒版）〈水生生物與環境〉；時光祕境島圖鑑「水生植物與魚」（池塘）', 'draft'),
  ('sci-fish-2', 'sci-fish', 'cat', 2, '{"q":"魚身上的部位各負責什麼？","cats":["往前游","轉彎和停下來","呼吸"],"cards":[{"t":"尾巴左右擺","c":0},{"t":"旁邊的鰭輕輕划","c":1},{"t":"頭兩邊的鰓一開一合","c":2}],"why":"尾巴左右擺推著身體往前；胸前和身旁的鰭負責轉彎、停住和保持平衡；鰓用來在水裡呼吸。"}'::jsonb, '國小自然四年級上學期（康軒版）〈水生生物與環境〉；時光祕境島圖鑑「水生植物與魚」（池塘）', 'draft'),
  ('sci-fish-3', 'sci-fish', 'tf', 2, '{"q":"池塘的水太髒、水草不見了，魚會比較難呼吸。","a":true,"why":"髒水裡的氧氣比較少，水草也能在水裡產生氧氣。水草不見、水又髒，魚就容易喘不過氣，所以要保持池塘乾淨。"}'::jsonb, '國小自然四年級上學期（康軒版）〈水生生物與環境〉；時光祕境島圖鑑「水生植物與魚」（池塘）', 'draft'),
  ('sci-survive-1', 'sci-survive', 'cat', 1, '{"q":"這些動物遇到危險時怎麼保護自己？","cats":["逃跑或躲起來","讓敵人看不清或嚇走敵人","捨棄身體一部分"],"cards":[{"t":"兔子快速跑回洞裡","c":0},{"t":"烏賊噴出墨汁","c":1},{"t":"壁虎斷掉尾巴","c":2},{"t":"刺河豚把身體脹大","c":1}],"why":"動物保護自己的方法很多：兔子靠逃跑躲藏；烏賊噴墨讓敵人看不清，河豚脹大嚇走敵人；壁虎斷尾，尾巴還會動吸引敵人，自己趁機逃走。"}'::jsonb, '國小自然五年級上學期（康軒版）〈動物世界〉動物如何求生存、延續生命（遊戲裡還沒有）', 'draft'),
  ('sci-survive-2', 'sci-survive', 'mc', 2, '{"q":"每年秋天，黑面琵鷺從北方飛到臺灣過冬，這叫做什麼？","opts":["遷徙","冬眠","偽裝"],"a":0,"why":"動物隨著季節搬到別的地方生活叫遷徙。黑面琵鷺冬天飛來臺南七股等地方，因為這裡比較暖、食物多；春天再飛回北方。"}'::jsonb, '國小自然五年級上學期（康軒版）〈動物世界〉動物如何求生存、延續生命（遊戲裡還沒有）', 'draft'),
  ('sci-survive-3', 'sci-survive', 'who', 3, '{"q":"有些青蛙身上是很鮮豔的顏色，為什麼？誰說得對？","says":[{"n":"小星","t":"提醒敵人「我有毒，不要吃我」"},{"n":"阿月","t":"因為牠們想被看到才好玩"},{"n":"小海","t":"顏色可以讓牠跳得更遠"}],"a":0,"why":"鮮豔的顏色叫「警戒色」，像是在告訴敵人自己有毒或很難吃。這和枯葉蝶的保護色剛好相反：一個要躲起來，一個要讓人看到。"}'::jsonb, '國小自然五年級上學期（康軒版）〈動物世界〉動物如何求生存、延續生命（遊戲裡還沒有）', 'draft'),
  ('sci-baby-1', 'sci-baby', 'cat', 1, '{"q":"這些動物是生蛋還是直接生出小寶寶？","cats":["生蛋（卵生）","直接生小寶寶（胎生）"],"cards":[{"t":"雞","c":0},{"t":"青蛙","c":0},{"t":"狗","c":1},{"t":"鯨魚","c":1},{"t":"海龜","c":0}],"why":"雞、青蛙、海龜都是生蛋，小寶寶從蛋裡孵出來，叫卵生；狗和鯨魚是媽媽肚子裡長大再生出來，叫胎生。鯨魚住在海裡，但牠是胎生、會餵奶的哺乳動物。"}'::jsonb, '國小自然五年級上學期（康軒版）〈動物世界〉動物如何求生存、延續生命（遊戲裡還沒有）', 'draft'),
  ('sci-baby-2', 'sci-baby', 'mc', 2, '{"q":"公孔雀把尾羽張開像一把大扇子，最主要是為了什麼？","opts":["吸引母孔雀","擋太陽","讓自己飛得更高"],"a":0,"why":"這是求偶行為。公孔雀張開漂亮的尾羽吸引母孔雀，螢火蟲用閃光找伴侶也是一樣，目的都是找到伴侶、生下下一代。"}'::jsonb, '國小自然五年級上學期（康軒版）〈動物世界〉動物如何求生存、延續生命（遊戲裡還沒有）', 'draft'),
  ('sci-baby-3', 'sci-baby', 'tf', 2, '{"q":"有些動物會照顧自己的寶寶，例如袋鼠媽媽把寶寶放在育兒袋裡長大。","a":true,"why":"袋鼠寶寶出生時很小，會在媽媽的育兒袋裡喝奶長大。照顧寶寶可以讓牠們比較容易活下來，這是動物延續生命的方法之一。"}'::jsonb, '國小自然五年級上學期（康軒版）〈動物世界〉動物如何求生存、延續生命（遊戲裡還沒有）', 'draft'),
  ('sci-planets-1', 'sci-planets', 'mc', 1, '{"q":"太陽系裡，我們住的地球是離太陽第幾近的行星？","opts":["第三","第一","第五"],"a":0,"why":"從太陽往外是水星、金星、地球、火星、木星、土星、天王星、海王星。地球排第三，不太熱也不太冷，剛好有液態的水。"}'::jsonb, '國小自然五年級上學期（康軒版）〈神祕的天空〉太陽系、四季星空（遊戲裡還沒有）；臺北市立天文科學教育館', 'draft'),
  ('sci-planets-2', 'sci-planets', 'mc', 2, '{"q":"太陽系裡最大的行星是哪一顆？","opts":["木星","地球","火星"],"a":0,"why":"木星是太陽系最大的行星，大約可以裝下一千多個地球。土星第二大，最有名的是它的光環。"}'::jsonb, '國小自然五年級上學期（康軒版）〈神祕的天空〉太陽系、四季星空（遊戲裡還沒有）；臺北市立天文科學教育館', 'draft'),
  ('sci-planets-3', 'sci-planets', 'order', 2, '{"q":"從離太陽最近的開始，排出這四顆行星。","steps":["水星","地球","木星","海王星"],"why":"記法：「水金地火木土天海」，水星最近、海王星最遠。地球在第三、木星在第五、海王星在最外面。"}'::jsonb, '國小自然五年級上學期（康軒版）〈神祕的天空〉太陽系、四季星空（遊戲裡還沒有）；臺北市立天文科學教育館', 'draft'),
  ('sci-stars-1', 'sci-stars', 'tf', 1, '{"q":"晚上的星星和太陽一樣，看起來會從東邊升起、往西邊落下。","a":true,"why":"因為地球自己在轉，所以從地上看，太陽、月亮和星星都像是從東邊升起、往西邊落下。只有北極星附近的星星看起來繞著它轉。"}'::jsonb, '國小自然五年級上學期（康軒版）〈神祕的天空〉太陽系、四季星空（遊戲裡還沒有）；臺北市立天文科學教育館', 'draft'),
  ('sci-stars-2', 'sci-stars', 'mc', 2, '{"q":"在北半球，可以用北斗七星找到哪一顆星，用來辨認北方？","opts":["北極星","織女星","天狼星"],"a":0,"why":"把北斗七星斗口的兩顆星連起來，往外延長大約五倍，就會找到北極星。北極星幾乎不動，看到它就知道哪邊是北方。"}'::jsonb, '國小自然五年級上學期（康軒版）〈神祕的天空〉太陽系、四季星空（遊戲裡還沒有）；臺北市立天文科學教育館', 'draft'),
  ('sci-stars-3', 'sci-stars', 'cat', 2, '{"q":"這些星星組成的「大三角」，各在哪個季節的晚上最好看？","cats":["夏季大三角","冬季大三角"],"cards":[{"t":"織女星","c":0},{"t":"牛郎星","c":0},{"t":"天狼星","c":1},{"t":"參宿四","c":1}],"why":"夏季大三角是織女星、牛郎星和天津四；冬季大三角是天狼星、參宿四和南河三。不同季節晚上看到的星星不一樣，所以叫四季星空。"}'::jsonb, '國小自然五年級上學期（康軒版）〈神祕的天空〉太陽系、四季星空（遊戲裡還沒有）；臺北市立天文科學教育館', 'draft'),
  ('sci-stars-4', 'sci-stars', 'who', 3, '{"q":"觀察星星時，星座盤要怎麼用？誰說得對？","says":[{"n":"帝雉台長","t":"轉到今天的日期和時間，再拿起來對著天空"},{"n":"小星","t":"隨便轉，看到哪個就是哪個"},{"n":"阿月","t":"只能在白天用"}],"a":0,"why":"星座盤要先把日期對上現在的時間，盤上露出來的就是現在看得到的星空，再對著方位拿高比對。星星晚上才看得到。"}'::jsonb, '國小自然五年級上學期（康軒版）〈神祕的天空〉太陽系、四季星空（遊戲裡還沒有）；臺北市立天文科學教育館', 'draft')
